import {transformSpirit} from './transformation.mjs';
import * as O from './offerings.mjs';
import {audio} from './audio.mjs';
import {ROSTER} from './roster.mjs';
import * as W from './world.mjs';
import * as E from './engine.mjs';
import {drawSpirit,drawPerson,drawTile,drawBuilding,drawTownDecor,drawTree,drawWell,drawTownBuilding,drawTownFeatures,renderSpiritCanvases} from './sprites.mjs';
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action=(name,label,value='',cls='btn')=>'<button class="'+cls+'" data-action="'+name+'" data-value="'+esc(value)+'">'+label+'</button>';
const chip=type=>'<span class="chip type-chip" style="--type:'+E.COLORS[type]+'">'+esc(type)+'</span>';
const sprite=(sp,form=0,size=128)=>'<canvas width="'+size+'" height="'+size+'" data-species="'+sp.id+'" data-form="'+form+'" role="img" aria-label="'+esc(sp.forms[form])+'"></canvas>';
let db,s,library={},view='explore',battle=null,selectedMove=0,style='normal',commit=.5,borrow=0,modal=null,toastTimer,saveTimer,keys=new Set(),lastStep=0,lastTime=performance.now(),ritual=null,queue=[],busy=false,aiStatus=null,starterChoices=[],starterBase='Beast',search='',filter='all',loaded=false,walkAnim=null,queuedStep=null,running=false,actionBusy=false,battleMode='main';
const PLAYTEST=new URLSearchParams(location.search).has('playtest');
const PLAYTEST_KEY=(new URLSearchParams(location.search).get('playtest')||'').replace(/[^a-z0-9-]/gi,'').slice(0,40);
const DB_NAME=PLAYTEST?'spirimon-playtest-v1'+(PLAYTEST_KEY?'-'+PLAYTEST_KEY:''):'spirimon-v1',COMPANION='http://127.0.0.1:4317';
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{req.result.createObjectStore('saves');req.result.createObjectStore('library',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbGet(store,key){return new Promise((resolve,reject)=>{const req=db.transaction(store).objectStore(store).get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbAll(store){return new Promise((resolve,reject)=>{const req=db.transaction(store).objectStore(store).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbPut(store,value,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite'),os=tx.objectStore(store);key===undefined?os.put(value):os.put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
let deviceSaveHandle=null,deviceWriteBusy=false,deviceWritePending=false;
function savePayload(){return{format:'spirimon-backup',version:E.VERSION,exportedAt:new Date().toISOString(),save:{...s,battle,generationQueue:queue},library:Object.values(library)};}
async function writeDeviceSave(){if(!deviceSaveHandle||deviceWriteBusy){if(deviceWriteBusy)deviceWritePending=true;return false;}deviceWriteBusy=true;try{const permission=await deviceSaveHandle.queryPermission({mode:'readwrite'});if(permission!=='granted')return false;const fileHandle=deviceSaveHandle.kind==='directory'?await deviceSaveHandle.getFileHandle('spirimon-save.json',{create:true}):deviceSaveHandle;const writer=await fileHandle.createWritable();await writer.write(JSON.stringify(savePayload()));await writer.close();return true;}catch(err){console.warn('Device save failed',err);return false;}finally{deviceWriteBusy=false;if(deviceWritePending){deviceWritePending=false;void writeDeviceSave();}}}
async function chooseDeviceSave(){if(!('showSaveFilePicker'in window)&&!('showDirectoryPicker'in window)){toast('This browser cannot link a folder for automatic saving. Use Export backup to save a file on your device.');return;}try{const handle='showDirectoryPicker'in window?await window.showDirectoryPicker({mode:'readwrite'}):await window.showSaveFilePicker({suggestedName:'spirimon-save.json',types:[{description:'Spirimon save',accept:{'application/json':['.json']}}]});if(await handle.requestPermission({mode:'readwrite'})!=='granted')return;deviceSaveHandle=handle;await dbPut('saves',handle,'device-file-handle');const ok=await writeDeviceSave();if(ok)await pruneBrowserStorage();toast(ok?'Device save linked. Automatic file saving enabled.':'File selected, but writing failed.');}catch(err){if(err.name!=='AbortError')toast('Cannot link save file: '+err.message);}}
async function pruneBrowserStorage(){if(!deviceSaveHandle)return;try{for(const key of ['before-original-roster','before-import']){const tx=db.transaction('saves','readwrite');tx.objectStore('saves').delete(key);}const tx=db.transaction('library','readwrite');tx.objectStore('library').clear();}catch(e){console.warn('Browser cleanup skipped',e);}}
async function restoreDeviceSaveHandle(){try{const handle=await dbGet('saves','device-file-handle');if(handle?.kind==='file'||handle?.kind==='directory')deviceSaveHandle=handle;}catch(err){console.warn('Cannot restore file permission',err);}}
async function persist(){if(!loaded)return;try{s.lastSave=Date.now();s.battle=battle;s.generationQueue=queue;const wrote=await writeDeviceSave();await dbPut('saves',structuredClone(s),'main');$('#save-status').innerHTML='<i></i> '+(wrote?'Saved to device file':deviceSaveHandle?'Browser fallback · file permission needed':PLAYTEST?'Playtest browser recovery':'Browser recovery saved');}catch(err){$('#save-status').textContent='Save failed · export a backup';console.error(err);}}
function save(){clearTimeout(saveTimer);const status=$('#save-status');if(status)status.textContent='Saving…';saveTimer=setTimeout(persist,350);}
function register(sp){E.refreshTechniques(sp);s.species[sp.id]=sp;library[sp.id]=sp;globalThis.spirimonSpecies=s.species;return sp;}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function note(msg){s.notes.unshift(msg);s.notes=s.notes.slice(0,100);save();}
const DAY_MS=35*60000,NIGHT_MS=25*60000,DAY_CYCLE_MS=DAY_MS+NIGHT_MS;
function isNight(){return (s.playTime||0)%DAY_CYCLE_MS>=DAY_MS;}
function mapWeather(){
 const reg=currentRegion(),phase=Math.floor((s.playTime||0)/(7*60000)),v=E.hash(s.seed,'weather',reg.key,phase)%1000;
 const kind=v<330?'rain':v<405?'snow':v<505?'wind':v<560?'heat':v<670?'fog':'clear';
 const h=E.hash(s.seed,'weather-options',reg.key,phase);
 return {kind,wind:kind==='wind'||((kind==='rain'||kind==='snow')&&h%3===0),lightning:(kind==='rain'||kind==='snow')&&Math.floor(h/7)%6===0,hail:kind==='rain'&&Math.floor(h/19)%8===0,heavy:kind==='snow'&&Math.floor(h/31)%3===0,phase};
}
function drawAtmosphere(ctx,width,height,time){
 const weather=mapWeather(),night=isNight();
 ctx.save();
 if(weather.kind==='snow'&&weather.heavy){ctx.fillStyle='#e8f2f54d';ctx.fillRect(0,0,width,height);}
 if(night){ctx.fillStyle='#06152c99';ctx.fillRect(0,0,width,height);}else{const cycle=(s.playTime||0)%DAY_CYCLE_MS;if(cycle>DAY_MS-180000){ctx.fillStyle='#c86e3629';ctx.fillRect(0,0,width,height);}}
 if(weather.kind==='heat'){ctx.fillStyle='#e9923326';ctx.fillRect(0,0,width,height);}
 if(weather.kind==='fog'){ctx.fillStyle='#cbd8d2a0';ctx.fillRect(0,0,width,height);for(let i=0;i<9;i++){ctx.fillStyle='#edf3e936';ctx.fillRect((i*127+time*.009)%(width+120)-120,(i*71)%height,140,24);}}
 if(weather.kind==='rain'||weather.kind==='snow'){
 const snow=weather.kind==='snow',count=snow?(weather.heavy?165:85):180;
 ctx.strokeStyle=snow?'#f8fcffcc':'#a8d4ed99';ctx.fillStyle='#f5faffdf';ctx.lineWidth=1;
 for(let i=0;i<count;i++){const x=(i*71+time*(snow?.012:(weather.wind?.15:.05)))%width,y=(i*131+time*(snow?.025:.16))%height;if(snow)ctx.fillRect(x,y,weather.heavy?3:2,weather.heavy?3:2);else{ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(weather.wind?9:3),y+11);ctx.stroke();}}
 if(weather.hail){ctx.fillStyle='#f7fcff';for(let i=0;i<55;i++)ctx.fillRect((i*97+time*.12)%width,(i*79+time*.22)%height,3,3);}
 }
 if(weather.kind==='wind'||weather.wind){ctx.strokeStyle='#dbece76b';for(let i=0;i<18;i++){const x=(i*113+time*.12)%width,y=(i*57)%height;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+25,y-3);ctx.stroke();}}
 if(weather.lightning&&time%11000<110){ctx.fillStyle='#e9f5ffae';ctx.fillRect(0,0,width,height);}
 ctx.restore();
 const badge=document.querySelector('#map-atmosphere')||document.createElement('div');
 if(!badge.id){badge.id='map-atmosphere';badge.style.cssText='position:absolute;top:76px;left:18px;z-index:7;padding:5px 9px;background:#142923bb;color:#fff6d6;font:11px monospace;border-radius:5px;pointer-events:none';document.querySelector('#world')?.parentElement?.appendChild(badge);}
 const label={rain:'Rain',snow:weather.heavy?'Heavy snow':'Snow',wind:'High winds',heat:'Heat wave',fog:'Heavy fog',clear:'Clear'}[weather.kind];
 const text=(night?'🌙 Night':'☀ Day')+' · '+label+(weather.lightning?' ⚡':'')+(weather.hail?' Hail':'')+(weather.wind&&weather.kind!=='wind'?' Gusts':'');
 if(badge.textContent!==text)badge.textContent=text;
}
function currentRegion(){const c=E.coord(s.player.x,s.player.y);return s.regions[c.cx+','+c.cy]||E.region(s.seed,c.cx,c.cy);}
function safe(){if(s.interior)return !battle;const c=E.coord(s.player.x,s.player.y);return currentRegion().town&&Math.abs(c.lx-24)<10&&Math.abs(c.ly-18)<8&&!battle;}
function party(){return s.party.map(id=>s.spirits.find(i=>i.id===id)).filter(Boolean);}
function lead(){return party().find(i=>i.hp>0);}
function spOf(i){const sp=s.species[i.species];return i.moveIds?{...sp,moves:i.moveIds.map((id,n)=>sp.learnset?.find(m=>m.id===id)||sp.moves[n])}:sp;}
function fieldSkill(kind){return party().filter(i=>i.hp>0).some(i=>{const sp=spOf(i),name=(sp.forms?.[i.appearance]||'').toLowerCase(),desc=(sp.description||'').toLowerCase(),types=[sp.base,sp.alter,...(sp.domains||[])];if(kind==='swim')return types.some(t=>['Water','Ooze'].includes(t))||desc.includes('aquatic')||desc.includes('swim')||desc.includes('fish')||desc.includes('seal');if(kind==='fly')return types.includes('Air')||/wing|bird|eagle|hawk|owl|bat|dragon|griff|phoenix|pegasus|fly|flying/.test(name+' '+desc);if(kind==='dig')return types.includes('Earth')||/burrow|dig|mole|badger|worm|ground|tunnel/.test(name+' '+desc);if(kind==='teleport')return types.some(t=>['Psychic','Fey','Aberration','Dreams','Space'].includes(t))||/teleport|portal|blink|warp|phase|spatial/.test(name+' '+desc);return false;});}
function abilityReady(kind){if(kind==='swim')return fieldSkill('swim');if(kind==='climb')return s.rank>=3&&party().some(i=>{const sp=spOf(i);return ['Giant','Beast','Construct'].includes(sp.base)||['Giant','Beast','Construct'].includes(sp.alter);});return fieldSkill(kind);}
function fieldTravel(kind,key){if(battle||s.interior)return toast('Field travel is unavailable here.');if(!fieldSkill(kind))return toast('No attuned Spirit can use '+kind+'.');if(kind==='fly'||kind==='teleport'){const reg=s.regions[key];if(!reg?.visited||!reg.town)return toast('Choose a previously visited town.');s.player.x=reg.cx*48+24;s.player.y=reg.cy*36+18;}else if(kind==='dig'){const towns=Object.values(s.regions).filter(x=>x.town&&x.visited);const reg=towns.find(x=>x.key===s.lastTown)||towns[0];if(!reg)return toast('No discovered town to return to.');s.player.x=reg.cx*48+24;s.player.y=reg.cy*36+18;}walkAnim=null;queuedStep=null;discoverRegion();save();render();toast(kind==='dig'?'Returned to a familiar town.':'Your Spirit carried you to the destination.');}
function fieldMenu(){const options=['fly','teleport','dig','swim'].map(k=>'<p><b>'+k.toUpperCase()+'</b> · '+(fieldSkill(k)?'Ready':'No eligible Spirit')+'</p>');const towns=Object.values(s.regions).filter(x=>x.visited&&x.town);showModal('Spirit field abilities.',options.join('')+'<div class="btn-row">'+(fieldSkill('dig')?action('field-use','Dig · Return to town','dig'):'')+(fieldSkill('swim')?'<span>Swim · Walk into water to cross it</span>':'')+'</div><p>Fly or Teleport to a visited town:</p><div class="btn-row">'+towns.flatMap(t=>['fly','teleport'].filter(fieldSkill).map(k=>action('field-use',k.toUpperCase()+' · '+esc(t.name),k+':'+t.key))).join('')+'</div>');}
function speciesFor(reg,r){if(s.settings.aiEnabled&&r()<.1)queueFresh(reg,r);const ready=Object.values(library).filter(p=>p&&p.id&&(p.atlas||p.sprites?.length===3)),local=ready.filter(p=>reg.biome.types.includes(p.base)),pool=local.length?local:ready;const known=pool.filter(p=>s.seen.includes(p.id));return register(E.pick(known.length&&r()<.9?known:pool.length?pool:Object.values(s.species).filter(p=>(p?.atlas||p?.proceduralArt)),r));}
function ensureRegion(cx,cy){const reg=E.region(s.seed,cx,cy);if(s.regions[reg.key])return s.regions[reg.key];Object.assign(reg,E.encounterRange(s.seed,cx,cy,s.townsVisited?.length||0));reg.danger=reg.minLevel;const r=E.rng(E.hash(s.seed,'ecosystem',cx,cy));s.regions[reg.key]={...reg,visited:false};const roam=[];for(let n=0;n<7;n++){const sp=speciesFor(reg,r);let x,y;for(let k=0;k<100;k++){x=cx*48+4+Math.floor(r()*40);y=cy*36+4+Math.floor(r()*28);const c=E.coord(x,y);if(E.walkable(E.tile(s.seed,x,y))&&(!reg.town||Math.abs(c.lx-24)>10||Math.abs(c.ly-18)>8))break;}const form=E.rollForm(r),level=E.encounterLevel(reg,r);const ind=E.heal(E.makeIndividual(sp,level,form,r),sp);roam.push({id:'r-'+reg.key+'-'+n,x,y,ind,active:true});}if(cx===0&&cy===0&&roam.length){roam[0].x=34;roam[0].y=18;}s.roamers[reg.key]=roam;return reg;}
function discoverRegion(){const c=E.coord(s.player.x,s.player.y);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)ensureRegion(c.cx+dx,c.cy+dy);const reg=s.regions[c.cx+','+c.cy];if(!reg.visited){reg.visited=true;if(reg.town&&reg.key!=='0,0'){s.townsVisited??=[];if(!s.townsVisited.includes(reg.key))s.townsVisited.push(reg.key);}note('Discovered '+reg.name+' in '+reg.biome.name+'.');toast(reg.name+' · '+reg.biome.name);}save();}
function discover(sp){if(!s.seen.includes(sp.id)){s.seen.push(sp.id);const pair=sp.base+'>'+sp.alter;s.history[pair]??=[];if(!s.history[pair].includes(sp.id))s.history[pair].push(sp.id);note('Encountered '+sp.forms[0]+' ('+sp.base+' → '+sp.alter+').');}}
const npcWander=new Map();
function townNPCs(cx,cy){return E.npcs(s.seed,cx,cy).map(n=>{const state=npcWander.get(n.id);return state?{...n,x:state.x,y:state.y,face:state.face||'down',walk:state.walk}:n;});}
function wanderNPCs(now){if(s.interior||modal||battle||view!=='explore')return;const p=E.coord(s.player.x,s.player.y);for(let cy=p.cy-1;cy<=p.cy+1;cy++)for(let cx=p.cx-1;cx<=p.cx+1;cx++){if(!E.region(s.seed,cx,cy).town)continue;const group=townNPCs(cx,cy);for(const n of group){let state=npcWander.get(n.id);if(!state){state={x:n.x,y:n.y,homeX:n.x,homeY:n.y,face:'down',next:now+4500+Math.random()*6000,walk:null};npcWander.set(n.id,state);}if(now<state.next)continue;state.next=now+6000+Math.random()*9000;if(Math.random()<.35)continue;const dirs=[[0,1],[1,0],[-1,0],[0,-1]],d=dirs[Math.floor(Math.random()*dirs.length)],nx=state.x+d[0],ny=state.y+d[1];if(Math.abs(nx-state.homeX)>3||Math.abs(ny-state.homeY)>3||!E.walkable(E.tile(s.seed,nx,ny))||buildingSpriteBlocked(nx,ny)||(nx===s.player.x&&ny===s.player.y)||group.some(other=>other.id!==n.id&&other.x===nx&&other.y===ny)||(s.roamers[cx+','+cy]||[]).some(r=>r.active&&r.x===nx&&r.y===ny)||W.buildings(cx,cy).some(b=>b.doorX===nx&&b.doorY===ny))continue;state.walk={x:state.x,y:state.y,start:now,duration:450};state.face=d[0]<0?'left':d[0]>0?'right':d[1]<0?'up':'down';state.x=nx;state.y=ny;}}}
function nearbyNPC(){if(s.interior)return W.roomNPCs(s.interior).find(n=>Math.abs(n.x-s.interior.x)+Math.abs(n.y-s.interior.y)<=2);const c=E.coord(s.player.x,s.player.y);return townNPCs(c.cx,c.cy).find(n=>Math.abs(n.x-s.player.x)+Math.abs(n.y-s.player.y)<=2);}
function nearbyRoamer(){if(s.interior)return null;const c=E.coord(s.player.x,s.player.y);return(s.roamers[c.cx+','+c.cy]||[]).filter(n=>n.active&&Math.abs(n.x-s.player.x)+Math.abs(n.y-s.player.y)<=2).sort((a,b)=>(Math.abs(a.x-s.player.x)+Math.abs(a.y-s.player.y))-(Math.abs(b.x-s.player.x)+Math.abs(b.y-s.player.y)))[0];}
function removeRoamer(id){for(const group of Object.values(s.roamers)){const r=group.find(x=>x.id===id);if(r)r.active=false;}}
function hint(){if(!s.starter)return'Your first bond awaits at the guild';const n=nearbyNPC();if(n)return'E · Talk to '+n.name;const r=nearbyRoamer();if(r)return'E · Approach '+spOf(r.ind).forms[r.ind.appearance];if(s.drops.some(d=>d.x===s.player.x&&d.y===s.player.y))return'E · Retrieve your dropped supplies';return safe()?'A safe place · Rest, train, and attune':'The wild is calling · Follow a trail';}
function hpHTML(ind,sp){const max=E.stats(ind,sp).hp,pct=Math.max(0,ind.hp/max*100);return'<div class="health '+(pct<25?'critical':pct<50?'low':'')+'"><i style="width:'+pct+'%"></i></div><div class="health-label"><span>'+(ind.status?esc(ind.status.toUpperCase()):'HP')+'</span><span>'+ind.hp+' / '+max+'</span></div><div class="pp-meter"><i style="width:'+Math.min(100,(ind.pp??E.stats(ind,sp).pp)/E.stats(ind,sp).pp*100)+'%"></i></div><div class="health-label"><span>SHARED PP</span><span>'+(ind.pp??E.stats(ind,sp).pp)+' / '+E.stats(ind,sp).pp+'</span></div>';}
function partyHTML(){const members=party();return'<section class="panel party-panel"><div class="section-label">ATTUNED SPIRITS <small>'+members.length+' / 6</small></div><div class="party-list">'+members.map((i,n)=>{const sp=spOf(i);return'<button class="party-item" data-action="detail" data-value="'+i.id+'">'+sprite(sp,i.appearance,80)+'<div class="party-info"><div class="party-name"><span>'+esc(sp.forms[i.appearance])+'</span><small>Lv. '+i.level+'</small></div><div class="party-types">'+esc(sp.base)+' / '+esc(sp.alter)+(n===0?' · LEAD':'')+'</div>'+hpHTML(i,sp)+'</div></button><div class="party-order">'+(n?action('party-up','↑',i.id,'btn small'):'')+(n<members.length-1?action('party-down','↓',i.id,'btn small'):'')+'</div>';}).join('')+Array.from({length:6-members.length},()=>'<div class="empty-slot"><span>◇</span> An unspoken bond</div>').join('')+'</div>'+action('view','Manage tattoos →','spirits','btn ghost party-manage')+'</section>';}
function miniMapHTML(){const c=E.coord(s.player.x,s.player.y),cells=[];for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const key=(c.cx+dx)+','+(c.cy+dy),r=s.regions[key];cells.push('<button type="button" class="mini-cell '+(!dx&&!dy?'here':'')+'" data-action="mini-region" data-value="'+key+'" title="'+(r?.visited?esc(r.name):'Unexplored')+'" style="background:'+(r?.visited?r.biome.color:'#24312d')+'" '+(!r?.visited?'disabled':'')+'>'+(!dx&&!dy?'◆':r?.town&&r.visited?'⌂':'')+'</button>');}return '<div class="mini-map" aria-label="Explored regions"><div class="mini-grid">'+cells.join('')+'</div>'+action('view','Full map','atlas','btn small')+'</div>';}
function exploreHTML(){const reg=currentRegion(),visited=Object.values(s.regions).filter(r=>r.visited).length;return'<div class="page-heading"><div><div class="eyebrow">YOUR JOURNEY, UNWRITTEN</div><h1>The wild is calling.</h1><p>Follow a trail. Find a spirit. Make a bond.</p></div><span class="pill gold">◇ &nbsp; Rank '+s.rank+' · '+rankName()+'</span></div><div class="explore-layout"><div><div class="world-frame"><canvas id="world" width="960" height="640" tabindex="0" aria-label="Explorable procedural world. Use arrow keys or WASD to move, E to interact."></canvas><div class="map-location"><small id="map-biome">'+esc((PLAYTEST?'PLAYTEST · ':'')+reg.biome.name.toUpperCase())+'</small><strong id="map-location">'+esc(reg.name)+'</strong></div><div class="map-controls">'+action('game-menu','MENU','','btn small')+' '+action('bag','BAG','','btn small')+'</div><div class="map-compass"><small>N</small><b>✧</b></div>'+miniMapHTML()+'<div class="dpad">'+['up','left','right','down'].map((d,i)=>action('step',['↑','←','→','↓'][i],d,'')).join('')+'</div><div class="map-hint" id="map-hint">'+esc(hint())+'</div>'+'<div class="map-coords" id="map-coords"></div></div><div class="world-toolbar"><div class="controls"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> move <span>·</span><kbd>E</kbd> interact <span>·</span><kbd>B</kbd> bag</div><div>'+action('bag','Bag','','btn ghost small')+'</div></div><div class="stat-strip"><div class="stat-block"><span class="stat-icon">♧</span><div><strong>'+s.seen.length+'</strong><small>Spirits discovered</small></div></div><div class="stat-block"><span class="stat-icon">◇</span><div><strong>'+s.spirits.length+'</strong><small>Bonds sealed</small></div></div><div class="stat-block"><span class="stat-icon">⌖</span><div><strong>'+visited+'</strong><small>Regions explored</small></div></div><div class="stat-block"><span class="stat-icon">◉</span><div><strong>'+s.inventory.coins+'</strong><small>Coin</small></div></div></div></div><aside class="right-column">'+partyHTML()+'<section class="field-note"><div class="eyebrow">A SEALER’S FIELD NOTE</div><h3>Not every bond begins in battle.</h3><p>Approach a roaming spirit with an offering. A little patience can turn a wary encounter into a willing companion.</p></section><section class="panel quest-preview"><div class="section-label">ON YOUR PATH <small>OPTIONAL</small></div><h3>'+(s.quests.discovery?'Beyond the familiar':'First impressions')+'</h3><p>'+(s.quests.discovery?'Visit three regions, then speak to Scholar Elin.':'Discover five spirit species, then visit Scholar Elin.')+'</p><div class="progress-line"><i style="width:'+Math.min(100,(s.quests.discovery?visited/3:s.seen.length/5)*100)+'%"></i></div></section></aside></div>';}
function rankName(){return['','Initiate','Wayfarer','Binder','Warden','Spiritkeeper','Elder'][Math.min(6,s.rank)];}
function render(){if(!loaded)return;audio.setScene(O.offeringActive()?'offering':battle?'battle':'map');globalThis.spirimonSpecies=s.species;$('#main').innerHTML=view==='explore'?(battle?battleHTML():exploreHTML()):view==='spirits'?collectionHTML():view==='atlas'?atlasHTML():journalHTML();document.querySelectorAll('.nav-button[data-action="view"]').forEach(b=>b.classList.toggle('active',b.dataset.value===view));$('#footer-seed').textContent='WORLD '+s.seed+' · LOCAL FIRST';$('.player-avatar').textContent=s.player.name.slice(0,1).toUpperCase();applyLayout();renderSpiritCanvases();if(battle&&view==='explore')drawBattle();}
function showModal(title,body,options={}){keys.clear();modal=options.kind||'generic';document.body.classList.add('modal-open');$('#modal-root').innerHTML='<div class="modal-overlay"><section class="modal '+(options.wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'">'+(options.lock?'':action('close','×','','modal-close'))+'<div class="eyebrow">SPIRIMON · '+esc(options.label||'THE SEALER’S FRONTIER')+'</div><h2>'+esc(title)+'</h2>'+body+'</section></div>';renderSpiritCanvases($('#modal-root'));$('#modal-root button:not(.modal-close),#modal-root input')?.focus({preventScroll:true});}
function closeModal(){O.cancelOffering();audio.setScene(battle?'battle':'map');queuedStep=null;ritual=null;modal=null;document.body.classList.remove('modal-open');$('#modal-root').innerHTML='';keys.clear();if(view==='explore')$('#world')?.focus({preventScroll:true});}
function starters(){showModal('Your first seal awaits.','<p>Welcome to Mossveil Crossing. You begin with no Spirit. Find a roaming Spirit, earn its trust through patience or an offering, then stabilize its tattoo seal.</p><label for="sealer-name">Your sealer’s name</label><input id="sealer-name" maxlength="24" placeholder="Your name"><div class="btn-row">'+action('begin-journey','Begin exploring','','btn primary')+'</div>',{lock:true,kind:'welcome'});}
function chooseStarter(id){const sp=s.species[id];if(!sp||s.starter)return;s.player.name=$('#sealer-name')?.value.trim().slice(0,24)||'Sealer';const i=E.heal(E.makeIndividual(sp,5),sp);i.bond=25;s.spirits.push(i);s.party.push(i.id);s.starter=true;discover(sp);closeModal();save();render();toast(sp.forms[0]+' is now attuned. Walk with WASD; press E to interact.');note('Formed the first bond with '+sp.forms[0]+'.');}
function collectionHTML(){const all=s.spirits.filter(i=>{const sp=spOf(i);return(!search||sp.forms.join(' ').toLowerCase().includes(search)||sp.base.toLowerCase().includes(search)||sp.alter.toLowerCase().includes(search))&&(filter!=='attuned'||s.party.includes(i.id));});return'<section class="tattoo-screen"><div class="tattoo-heading"><h1>SPIRIT TATTOOS</h1><span>'+s.party.length+' / 6 attuned</span>'+action('view','Return','explore')+'</div><p class="notice">'+(safe()?'A safe place. Rest, train, and attune your bonds.':'Visit a safe place to change attunement.')+'</p><div class="collection-toolbar"><input id="spirit-search" aria-label="Search spirits" placeholder="Find a Spirit" value="'+esc(search)+'"><select id="spirit-filter" aria-label="Filter spirits"><option value="all">All tattoos</option><option value="attuned" '+(filter==='attuned'?'selected':'')+'>Attuned</option></select>'+action('rest','Rest')+'</div><div class="tattoo-list">'+all.map(i=>{const sp=spOf(i);return'<button class="tattoo-row '+(s.party.includes(i.id)?'attuned':'')+'" data-action="detail" data-value="'+i.id+'">'+sprite(sp,i.appearance,112)+'<div><strong>'+esc(sp.forms[i.appearance])+'</strong><p>'+esc(sp.base)+' / '+esc(sp.alter)+' · '+esc(i.nature)+'</p>'+hpHTML(i,sp)+'</div><span>Lv. '+i.level+'<small>'+(s.party.includes(i.id)?'ATTUNED':'RESERVE')+'</small></span></button>';}).join('')+(!all.length?'<p class="notice">No tattoos yet. Approach a roaming Spirit to begin your first bond.</p>':'')+'</div></section>';}
function detail(id){const i=s.spirits.find(i=>i.id===id);if(!i)return;const sp=spOf(i),st=E.stats(i,sp);showModal(sp.forms[i.appearance],'<div class="detail-top">'+sprite(sp,i.appearance,180)+'<div><div class="pill gold">Level '+i.level+' · Form '+(i.form+1)+'</div><div style="margin:10px 0">'+chip(sp.base)+chip(sp.alter)+sp.domains.map(d=>'<span class="chip">'+esc(d)+'</span>').join('')+'</div><p>'+esc(i.nature)+' · '+esc(sp.temperament)+'</p><p>Ability: '+esc(sp.ability)+'<br><span class="tiny">'+esc(({Steadfast:'Reduce incoming damage while guarded.',Wildheart:'Stronger physical moves.',Soulweave:'Stronger spiritual moves.','Second Wind':'Recover health once per battle when badly hurt.'})[sp.ability])+'</span><br>Bond '+i.bond+' · '+(s.party.includes(id)?'Attuned':'Resting in a tattoo')+'</p></div></div><p>'+esc(sp.description)+'</p><div class="detail-stats"><div><strong>'+st.hp+'</strong><small>Health</small></div><div><strong>'+st.power+'</strong><small>Combined power</small></div><div><strong>'+st.speed+'</strong><small>Speed</small></div></div>'+hpHTML(i,sp)+'<p class="tiny" style="margin-top:10px">Physical resistance: '+(sp.physicalRes<1?'Resistant':'Normal')+' · Spiritual resistance: '+(sp.spiritualRes<1?'Resistant':'Normal')+'<br>Next transformation: '+(i.form===2?'Final form unlocked':'level '+(i.form===0?16:36)+(sp.evolution==='bond'?' and bond 60':''))+' · XP '+i.xp+' / '+i.level*18+'</p><div class="subheading">APPEARANCE · COSMETIC ONLY</div><div class="form-row">'+sp.forms.map((f,n)=>'<button data-action="appearance" data-value="'+id+':'+n+'" '+(n>i.form?'disabled':'')+' class="'+(i.appearance===n?'selected':'')+'">'+sprite(sp,n,96)+'<small>'+(n>i.form?'Locked':esc(f))+'</small></button>').join('')+'</div><div class="move-list">'+sp.moves.map(m=>'<div><span>'+esc(m.name)+'<small> · '+m.kind+'</small></span><small>Power '+m.power+' · PP '+E.moveCost(m)+' · Speed '+(m.speed>=0?'+':'')+m.speed+'</small></div>').join('')+'</div><div class="btn-row">'+action('attune',s.party.includes(id)?'Unattune':'Attune spirit',id)+action('lead','Make lead spirit',id)+action('train','Train · 25 Coin',id)+action('bond','Share offering',id)+action('learn-menu','Practice moves',id)+'</div><p class="help-line">Design: '+(sp.source==='local-llm'?'local AI model':sp.atlas?'original shared lineage':'validated local lineage')+' · Art: '+(sp.atlas?'original three-form sprite set':sp.sprites?.length===3?'local image model':'awaiting complete artwork')+'</p>');}
function attune(id){if(battle)return toast('Finish the battle first.');if(!safe())return toast('Change attunement at a town or guild.');if(s.party.includes(id)){if(s.party.length===1)return toast('Keep at least one spirit attuned.');s.party=s.party.filter(x=>x!==id);}else{if(s.party.length>=6)return toast('Six spirits are already attuned.');s.party.push(id);}save();detail(id);render();}
function training(id){if(!safe())return toast('Train at a town or guild.');if(s.inventory.coins<25)return toast('Training costs 25 Coin.');const i=s.spirits.find(x=>x.id===id);if(!i)return;s.inventory.coins-=25;i.trained=Math.min(60,i.trained+2);i.bond=Math.min(100,i.bond+3);const previous=i.appearance,result=E.gainXP(i,spOf(i),Math.max(70,i.level*10));if(result.evolved)transformSpirit(spOf(i),previous,i.appearance);save();detail(id);render();toast(result.evolved?'A new transformation awakens!':result.levels?'Training complete. Level '+i.level+'.':'Training strengthens your bond and power.');}
function shareOffering(id){if(battle)return;if(s.inventory.offerings<1)return toast('You need an offering.');const i=s.spirits.find(x=>x.id===id);if(!i)return;s.inventory.offerings--;i.bond=Math.min(100,i.bond+12);const result=E.gainXP(i,spOf(i),0);save();detail(id);render();toast(result.evolved?'Your bond awakens a new transformation.':'Your bond deepens.');}
function rest(){if(!safe())return toast('Rest at a town or guild.');party().forEach(i=>E.heal(i,spOf(i)));s.safe={x:s.player.x,y:s.player.y};save();render();toast('Your attuned spirits are fully restored. This is now your recovery point.');}
function atlasHTML(){const c=E.coord(s.player.x,s.player.y),cells=[],radius=innerWidth<560?2:3;for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){const cx=c.cx+dx,cy=c.cy+dy,reg=s.regions[cx+','+cy];cells.push(reg?.visited?'<button class="atlas-cell '+(!dx&&!dy?'current':'')+'" data-action="region-info" data-value="'+reg.key+'" style="background:'+reg.biome.color+'55"><small>'+cx+', '+cy+(reg.town?' · GUILD':'')+'</small><strong>'+esc(reg.name)+'</strong><small>'+esc(reg.biome.name)+' · Lv. '+reg.danger+'+</small></button>':'<div class="atlas-cell unknown" aria-label="Unexplored region">·</div>');}return'<div class="page-heading"><div><div class="eyebrow">THERE IS ALWAYS ANOTHER TRAIL</div><h1>Your world, unfolding.</h1><p>Discovered places stay where you left them. Walk beyond the edge to find more.</p></div><span class="pill">'+Object.values(s.regions).filter(r=>r.visited).length+' regions mapped</span></div><div class="panel"><div class="atlas-grid">'+cells.join('')+'</div><p class="help-line" style="text-align:center">Your location is outlined in gold. Region danger stays fixed as your spirits grow.</p></div>';}
function journalHTML(){const visited=Object.values(s.regions).filter(r=>r.visited).length,quests=[['discovery','First impressions','Discover five different spirit species, then report to Scholar Elin.',s.seen.length+'/5 species · Reward: 50 renown'],['rival','A friendly rivalry','Defeat Rowan in an organized guild battle.',s.wins+' victories · Reward: guild rank progress'],['explorer','Beyond the familiar','Visit three regions and share your findings with Scholar Elin.',visited+'/3 regions · Reward: 50 renown']];return'<div class="page-heading"><div><div class="eyebrow">NO DESTINY REQUIRED</div><h1>A journey of your own.</h1><p>Small promises, familiar faces, and whatever lies around the next bend.</p></div><span class="pill">Rank '+s.rank+' · '+s.rankXP+' / '+s.rank*100+' renown</span></div><div class="journal-grid"><div class="panel"><div class="section-label">GUILD NOTICES <small>ALL OPTIONAL</small></div>'+quests.map(([id,title,desc,progress])=>'<div class="quest '+(s.quests[id]?'quest-complete':'')+'"><h3>'+(s.quests[id]?'✓ ':'')+title+'</h3><p>'+desc+'</p><small>'+(s.quests[id]?'Completed':progress)+'</small></div>').join('')+'<div class="subheading">PEOPLE YOU KNOW</div>'+['Keeper Iona','Tavi','Rowan','Scholar Elin'].map((name,n)=>{const role=['keeper','merchant','rival','scholar'][n],value=Object.entries(s.friendships).filter(([k])=>k.startsWith(role)).reduce((sum,[,v])=>sum+v,0);return'<div class="friend-row"><span>'+name+'</span><span class="muted">'+(value>15?'Friend':value>3?'Acquaintance':'New face')+' · '+value+'</span></div>';}).join('')+'</div><div class="panel"><div class="section-label">FIELD JOURNAL</div>'+s.notes.slice(0,18).map(n=>'<p class="journal-entry">'+esc(n)+'</p>').join('')+'</div></div>';}

function buildingSpriteBlocked(x,y){const p=E.coord(x,y);if(!E.region(s.seed,p.cx,p.cy).town)return false;const buildings=W.buildings(p.cx,p.cy);if(buildings.some(b=>{const left=b.footX,right=b.footX+b.w-1,top=b.footY,bottom=b.footY+b.h-1;if(x===b.doorX&&y===b.doorY)return false;return x>=left&&x<=right&&y>=top&&y<=bottom;}))return true;return W.featureFootprintBlocked(p.lx,p.ly);}
function move(dx,dy){if(s.interior)return moveInside(dx,dy);if(modal||battle||view!=='explore'||!s.starter)return;if(walkAnim&&performance.now()-walkAnim.start<walkAnim.duration){queuedStep=[dx,dy];return;}const x=s.player.x+dx,y=s.player.y+dy;s.player.face=dx<0?'left':dx>0?'right':dy<0?'up':'down';const c=E.coord(x,y);const door=E.region(s.seed,c.cx,c.cy).town&&W.buildings(c.cx,c.cy).find(b=>b.doorX===x&&b.doorY===y);if(door&&dy===-1)return enterBuilding(door);const n=townNPCs(c.cx,c.cy).find(n=>n.x===x&&n.y===y);if(n){talk(n);return;}const targetTile=E.tile(s.seed,x,y),terrainBlocked=!E.walkable(targetTile,abilityReady('swim'),abilityReady('climb')),propBlocked=buildingSpriteBlocked(x,y);if(terrainBlocked||propBlocked){const reason=terrainBlocked?'terrain '+targetTile:'building or prop footprint';const msg='Blocked at '+x+','+y+' ('+reason+')';$('#map-hint').textContent=msg;if(!window.lastCollisionNotice||performance.now()-window.lastCollisionNotice>2200){toast(msg);window.lastCollisionNotice=performance.now();}return;}walkAnim={x:s.player.x,y:s.player.y,start:performance.now(),duration:running||keys.has('shift')?100:170};lastStep=performance.now();s.player.x=x;s.player.y=y;s.steps++;discoverRegion();if(currentRegion().town)s.lastTown=currentRegion().key;const roamer=nearbyRoamer();if(roamer&&roamer.x===x&&roamer.y===y){approach(roamer);return;}if(!currentRegion().town&&s.steps>8&&Math.random()<(isNight()?.15:.075)){const reg=currentRegion(),sp=speciesFor(reg,Math.random),form=E.rollForm();const ind=E.heal(E.makeIndividual(sp,E.encounterLevel(reg),form),sp);if(lead())startBattle(ind);else{const encounter={id:'first-wild-'+s.steps,x,y,ind,active:true};(s.roamers[reg.key]||(s.roamers[reg.key]=[])).push(encounter);approach(encounter);}return;}$('#map-hint').textContent=hint();$('#map-location').textContent=currentRegion().name;$('#map-biome').textContent=(PLAYTEST?'PLAYTEST · ':'')+currentRegion().biome.name.toUpperCase();save();}
function interact(){if(modal||battle||!s.starter)return;const pos=E.coord(s.player.x,s.player.y),door=!s.interior&&W.buildings(pos.cx,pos.cy).find(b=>b.doorX===s.player.x&&b.doorY===s.player.y-1);if(door)return enterBuilding(door);const drop=s.drops.find(d=>Math.abs(d.x-s.player.x)+Math.abs(d.y-s.player.y)<=1);if(drop){for(const key of['seals','offerings','tonics','ethers'])s.inventory[key]+=drop.items[key]||0;s.drops=s.drops.filter(d=>d!==drop);save();render();toast('Recovered your dropped supplies.');return;}const n=nearbyNPC();if(n)return talk(n);const r=nearbyRoamer();if(r)return approach(r);if(safe())return showModal('A moment to breathe.','<p>The guild lamps are lit. Rest your spirits, adjust your tattoos, or prepare for the next trail.</p><div class="btn-row">'+action('rest-close','Rest and recover')+action('collection-close','Manage tattoos')+'</div>');toast('Move closer to a person or roaming spirit, then press E.');}
function approach(roamer){if(!roamer.active)return;const sp=spOf(roamer.ind);discover(sp);showModal('A spirit watches you.','<div class="detail-top">'+sprite(sp,roamer.ind.appearance,180)+'<div><h3>'+esc(sp.forms[roamer.ind.appearance])+'</h3>'+chip(sp.base)+chip(sp.alter)+'<p>Level '+roamer.ind.level+' · '+esc(sp.temperament)+'</p></div></div><p>'+esc(sp.description)+'</p><p style="margin-top:12px">You could challenge it, or give it a reason to trust you.</p><div class="btn-row">'+(lead()?action('wild-battle','Challenge',roamer.id,'btn primary'):'')+(s.spirits.length===0?action('free-first-seal','Seal as your first Spirit · FREE',roamer.id,'btn primary'):'')+(!roamer.offeringAttempted?action('offer','Prepare an offering',roamer.id):'<p>Cooperation attempt already used.</p>')+action('close','Leave in peace','','btn ghost')+'</div>');save();}
function findRoamer(id){return Object.values(s.roamers).flat().find(r=>r.id===id);}
function cooperate(id){const r=findRoamer(id);if(!r?.active)return;const sp=spOf(r.ind);audio.setScene('offering');O.prepareOffering({roamer:r,sp:{...sp,form:r.ind.form},inventory:s.inventory,settings:s.settings,persist,notice:toast,open:(title,html)=>showModal(title,html,{kind:'offering'}),onSuccess:()=>{capture(structuredClone(r.ind),id);closeModal();save();render();},onFailure:message=>{save();audio.setScene('map');showModal('The offering ends.','<p>'+esc(message)+' This individual cannot receive another offering. It remains available for battle and a battle seal.</p><div class="btn-row">'+(lead()?action('wild-battle','Challenge',id):'')+action('close','Leave')+'</div>');}});}
function sealPulse(){}
function newSealProfile(ind){const sp=spOf(ind),st=E.stats(ind,sp);const measurement=(v,unit)=>v==null?'Not yet recorded':esc(String(v))+' '+unit;showModal('New Spirit discovered · '+sp.forms[ind.appearance],'<div class="detail-top">'+sprite(sp,ind.appearance,180)+'<div><h3>'+esc(sp.forms[ind.appearance])+'</h3>'+chip(sp.base)+chip(sp.alter)+'<p>Level '+ind.level+' · '+esc(ind.nature)+'</p><p>Height: '+measurement(sp.height,'')+'<br>Weight: '+measurement(sp.weight,'')+'</p></div></div><div class="detail-stats"><div><strong>'+st.hp+'</strong><small>HP</small></div><div><strong>'+st.power+'</strong><small>Power</small></div><div><strong>'+st.speed+'</strong><small>Speed</small></div><div><strong>'+st.pp+'</strong><small>PP</small></div></div><div class="subheading">BEHAVIOR</div><p>Temperament: '+esc(sp.temperament||'Unknown')+' · Nature: '+esc(ind.nature)+'<br>Ability: '+esc(sp.ability||'Unknown')+'</p><div class="subheading">FIELD DESCRIPTION</div><p>'+esc(sp.description||'No field description recorded.')+'</p><p class="help-line">Height and weight will appear when recorded in the species field guide.</p><div class="btn-row">'+action('close','Continue exploring','','btn primary')+action('view','View Spirit collection','spirits')+'</div>',{wide:true});}
function capture(ind,roamer){const sp=spOf(ind);if(s.spirits.some(i=>i.id===ind.id))return;const firstOfSpecies=!s.spirits.some(i=>i.species===ind.species);ind.bond=25;E.heal(ind,sp);s.spirits.push(ind);if(s.party.length<6)s.party.push(ind.id);s.captured++;discover(sp);if(roamer)removeRoamer(roamer);note('Sealed a bond with '+sp.forms[ind.appearance]+'.');renown(20);save();toast(sp.forms[ind.appearance]+' is sealed into a new tattoo.');if(firstOfSpecies)queueMicrotask(()=>newSealProfile(ind));}
function renown(value){s.rankXP+=value;while(s.rank<6&&s.rankXP>=s.rank*100){s.rankXP-=s.rank*100;s.rank++;note('Earned guild rank '+s.rank+': '+rankName()+'.');}}
function talk(n){s.friendships[n.id]??=0;const intro=s.friendships[n.id]>15?'It’s good to see you again, '+s.player.name+'. ':'';let body='';if(n.role==='resident')body='<p>Come in, traveler. Our doors are open to sealers. Spirits respond to patience: offer food, watch their mood, and let trust grow before attempting a seal.</p><div class="btn-row">'+action('chat','Share a story',n.id)+'</div>';if(n.role==='keeper')body='<p>'+esc(intro)+'A seal is a promise, not a prison. There’s room for many bonds beneath your skin, but only six can be awake at once.</p><div class="btn-row">'+action('rest-close','Restore spirits','','btn primary')+action('collection-close','Attune tattoos')+action('chat','Share a story',n.id)+'</div>';
if(n.role==='merchant')body='<p>'+esc(intro)+'A full pack makes for a longer trail. What do you need?</p><p style="margin-top:10px;color:var(--gold)">'+s.inventory.coins+' Coin available</p><div class="btn-row">'+action('buy','Seal catalyst · 12 Coin','seals')+action('buy','Offering · 8 Coin','offerings')+action('buy','Tonic · 10 Coin','tonics')+action('buy','Soul draught · 16 Coin','ethers')+action('buy','Herbs · 5 Coin','herbs')+action('buy','Incense · 8 Coin','incense')+action('buy','Ore · 6 Coin','ore')+action('buy','Improve seals · 100 Coin','quality')+'</div><div class="modal-section"><p>Bring three spare catalysts and I’ll trade you a tonic.</p><div class="btn-row">'+action('trade-items','Trade 3 catalysts → 1 tonic')+action('chat','Share a story',n.id)+'</div></div>';
if(n.role==='rival')body='<p>'+esc(intro)+'I’ve been training. Ready for a friendly match? Guild matches follow your rank, so neither of us gets too comfortable.</p><div class="btn-row">'+action('trainer','Battle Rowan','','btn primary')+action('npc-trade','Trade spirits')+action('chat','Share a story',n.id)+'</div>';
if(n.role==='scholar')body='<p>'+esc(intro)+'Each spirit is a question the world hasn’t answered yet. Bring me your discoveries; I’ll help fund the next expedition.</p><div class="btn-row">'+action('claim','Report five species','discovery')+action('claim','Report three regions','explorer')+action('chat','Share a story',n.id)+'</div>';s.activeNPC=n;showModal(n.name,body,{label:n.role==='merchant'?'TRAIL SUPPLIES':'A FAMILIAR FACE'});}
function chat(id){const last=s.chatSteps?.[id]??-100;if(s.steps-last<10)return toast('You’ve caught up for now. Come back after exploring.');s.chatSteps??={};s.chatSteps[id]=s.steps;s.friendships[id]=(s.friendships[id]||0)+4;renown(5);note('Shared a story with '+s.activeNPC.name+'.');save();toast('Your friendship with '+s.activeNPC.name+' grows.');}
function buy(item){const cost={seals:12,offerings:8,tonics:10,ethers:16,herbs:5,incense:8,ore:6,quality:100}[item];if(!cost)return;if(s.inventory.coins<cost)return toast('Not enough Coin.');if(item==='quality'&&s.inventory.quality>=3)return toast('Your seal catalysts are already masterwork quality.');s.inventory.coins-=cost;s.inventory[item]=(s.inventory[item]||0)+1;save();talk(s.activeNPC);render();toast(item==='quality'?'Seal quality improved.':'Supplies added to your bag.');}
function claim(which){const ready=which==='discovery'?s.seen.length>=5:Object.values(s.regions).filter(r=>r.visited).length>=3;if(s.quests[which])return toast('You’ve already received this reward.');if(!ready)return toast('Keep exploring. Your discoveries will be here when you return.');s.quests[which]=true;renown(50);note('Completed '+(which==='discovery'?'First impressions':'Beyond the familiar')+'.');save();talk(s.activeNPC);render();toast('Report accepted. +50 renown.');}
function tradeSpirit(){if(battle||!safe())return;const spare=s.spirits.filter(i=>!s.party.includes(i.id));if(!spare.length)return toast('Keep a spirit in reserve to offer Rowan a trade.');const offer=spare[0],sp=speciesFor(currentRegion(),Math.random),incoming=E.heal(E.makeIndividual(sp,Math.max(3,offer.level)),sp);s.trade={out:offer.id,incoming};showModal('A fair exchange.','<p>Rowan offers '+esc(sp.forms[0])+' (Lv. '+incoming.level+') for your reserve '+esc(spOf(offer).forms[offer.appearance])+'.</p><div style="text-align:center">'+sprite(sp,0,160)+'</div><div class="btn-row">'+action('confirm-trade','Accept trade','','btn primary')+action('close','Keep my spirit','','btn ghost')+'</div>');}
function bag(){showModal('Ready for the trail.','<p>Your supplies travel with you. Tavi sells more in town.</p><div class="bag-grid"><div><strong>'+s.inventory.seals+'</strong><small>Seal catalysts</small></div><div><strong>'+s.inventory.offerings+'</strong><small>Offerings</small></div><div><strong>'+s.inventory.tonics+'</strong><small>Tonics</small></div></div><p style="margin-top:20px">Herbs: '+(s.inventory.herbs||0)+' · Incense: '+(s.inventory.incense||0)+' · Ore: '+(s.inventory.ore||0)+'<br>Coin: '+s.inventory.coins+' · Seal quality: '+['','Standard','Refined','Masterwork'][s.inventory.quality]+'</p><div class="btn-row">'+action('tonic','Use tonic on lead spirit')+action('ether','Restore shared PP · '+(s.inventory.ethers||0))+action('export','Export save backup','','btn ghost')+'</div><p class="help-line">Tonics restore half a spirit’s maximum health. During battle, using one takes your action.</p>');}
function useTonic(){if(!s.inventory.tonics)return toast('No tonics remaining.');const i=battle?s.spirits.find(x=>x.id===battle.ally):lead();if(!i)return toast('No active spirit can receive a tonic.');const max=E.stats(i,spOf(i)).hp;if(i.hp>=max)return toast('Your spirit is already healthy.');s.inventory.tonics--;i.hp=Math.min(max,i.hp+Math.ceil(max*.5));closeModal();if(battle)enemyOnly('You use a tonic.');else{save();render();toast('Your lead spirit recovers health.');}}
function startBattle(enemy,roamer=null,trainer=false){const ally=lead();if(!ally)return toast('Your spirits need rest at the guild.');closeModal();party().forEach(i=>i.secondWindUsed=false);enemy.secondWindUsed=false;discover(spOf(enemy));battle={enemy:structuredClone(enemy),ally:ally.id,roamer,trainer,round:1,log:[trainer?'Rowan challenges you to a guild match.':'A wild '+spOf(enemy).forms[enemy.appearance]+' draws near.'],supportUsed:false,credits:{a:0,b:0}};borrow=0;commit=ally.commit;style='normal';selectedMove=0;view='explore';save();render();}
function trainerBattle(){const r=E.rng(E.hash(s.seed,'rowan',s.rank,s.wins)),sp=speciesFor(currentRegion(),r);startBattle(E.heal(E.makeIndividual(sp,4+s.rank*3,0,r),sp),null,true);}
function battleHTML(){
 const ally=s.spirits.find(i=>i.id===battle.ally),asp=spOf(ally),enemy=battle.enemy,esp=spOf(enemy),credits=battle.credits||{a:0,b:0};
 let controls='';
 if(battleMode==='main')controls='<div class="classic-actions">'+action('battle-fight','FIGHT','','fight')+action('battle-bag','BAG','','bag')+action('battle-switch','SPIRITS','','spirits')+action(battle.trainer?'yield':'flee',battle.trainer?'YIELD':'RUN','','run')+'</div>';
 if(battleMode==='moves')controls='<div class="classic-moves">'+asp.moves.map((m,n)=>'<button data-action="move-select" data-value="'+n+'" class="classic-move"><b>'+esc(m.name)+'</b><small>'+esc(m.type)+' · '+E.moveCategory(m)+' · '+E.moveCost(m)+' PP</small></button>').join('')+'</div>'+action('battle-main','‹ Back','','battle-back');
 if(battleMode==='tactics'){const move=asp.moves[selectedMove];controls='<div class="compact-tactics"><div class="tactic-row"><div class="compact-styles">'+['agile','normal','strong'].map(t=>action('style',t[0].toUpperCase()+t.slice(1),t,style===t?'selected':'')).join('')+'</div><select id="borrow-select" aria-label="Borrow extra actions">'+[0,1,2].map(n=>'<option value="'+n+'" '+(borrow===n?'selected':'')+'>'+(n?'Borrow +'+n:'1 action')+'</option>').join('')+'</select></div><div class="compact-commit"><span>DEF</span><input id="commitment" type="range" min="0" max="100" value="'+Math.round(commit*100)+'" aria-label="Attack commitment"><span>ATK</span></div><div class="tactic-row">'+action('battle-moves','‹ Moves','','battle-back')+'<span class="tactic-cost">'+totalActionCost()+' PP · '+speedHint().replace('LIKELY ','')+'</span>'+action('battle-act','USE '+esc(move.name),'','use-move')+(E.moveCategory(move)!=='Status'&&!ally.omegaUsed?action('omega-act','Ω OMEGA MOVE','','use-move'):'')+'</div></div>';}
 if(battleMode==='bag')controls='<div class="classic-actions bag-actions">'+action('tonic','TONIC ×'+s.inventory.tonics,'','bag')+action('ether','SOUL DRAUGHT ×'+(s.inventory.ethers||0),'','spirits')+(!battle.trainer?action('battle-seal','SEAL ×'+s.inventory.seals,'','fight'):action('battle-record','RECORD','','run'))+action('support','SEALER’S WARD','','spirits')+action('battle-switch','SPIRITS','','bag')+action('battle-main','BACK','','run')+'</div>';
 const speech=battleMode==='moves'?'Choose a move. All four moves share one PP pool.':battleMode==='tactics'?esc(asp.moves[selectedMove].desc)+(borrow?' Borrow '+borrow+' now; your foe gains '+borrow+' bonus action(s) next round.':' Set your style and attack commitment.'):battle.message?esc(battle.message):'What should '+esc(asp.forms[ally.appearance])+' do?';
 return'<section class="classic-battle"><div class="classic-stage"><canvas id="battle-canvas" width="1000" height="550" aria-label="Spirit battle"></canvas><div class="classic-hud enemy"><div class="hud-name">'+esc(esp.forms[enemy.appearance])+'<small>Lv.'+enemy.level+'</small></div>'+hpHTML(enemy,esp)+'</div><div class="classic-hud ally"><div class="hud-name">'+esc(asp.forms[ally.appearance])+'<small>Lv.'+ally.level+'</small></div>'+hpHTML(ally,asp)+'</div><div class="battle-corner"><span>ROUND '+battle.round+'</span>'+action('battle-record','LOG','','')+'</div></div><div class="classic-bottom"><div class="classic-dialogue"><p id="battle-speech">'+speech+'</p><div class="debt-indicator">'+(credits.a?'YOUR BONUS +'+credits.a+' ':'')+(credits.b?'FOE BONUS +'+credits.b:'')+'</div></div><div class="classic-control">'+controls+'</div></div></section>';
}
function totalActionCost(){if(!battle)return 0;const i=s.spirits.find(i=>i.id===battle.ally),m=spOf(i).moves[selectedMove];let cost=0;for(let n=0;n<1+(battle.credits?.a||0)+borrow;n++)cost+=E.actionCost(m,n);return cost;}
function drawBattle(anim=null){
 const canvas=$('#battle-canvas');if(!canvas||!battle)return;const rect=canvas.getBoundingClientRect(),H=Math.max(240,Math.round(1000*rect.height/Math.max(1,rect.width)));if(canvas.height!==H)canvas.height=H;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;
 const reg=currentRegion(),ash=reg.biome.kind==='ash',fen=reg.biome.kind==='fen';
 const colors=ash?['#c4b77c','#b1a765','#9d9656','#8f8849']:fen?['#9bc6aa','#7bb797','#5c9c7c','#4d8968']:['#b4df8c','#9ad177','#81bc63','#70aa54'];
 c.fillStyle=colors[0];c.fillRect(0,0,1000,H);
 for(let band=0;band<20;band++){c.fillStyle=colors[Math.min(3,Math.floor(band/6))];c.fillRect(0,Math.floor(band*H/20),1000,Math.ceil(H/20));for(let n=0;n<9;n++){c.fillStyle=band%2?'#d5e8a51c':'#285d2f14';c.fillRect((n*137+band*39)%1000,band*H/20+8,75+band*4,3);}}
 const platform=(x,y,rx,ry)=>{c.fillStyle=ash?'#8e7851':fen?'#47795d':'#5d8e42';c.beginPath();c.ellipse(x,y,rx,ry+6,0,0,Math.PI*2);c.fill();c.fillStyle=ash?'#c8b785':fen?'#97bd8e':'#b7c881';c.beginPath();c.ellipse(x,y-5,rx-4,ry,0,0,Math.PI*2);c.fill();c.fillStyle=ash?'#aa9a67':fen?'#5d9a70':'#82ae57';for(let n=0;n<70;n++){const r=E.rng(E.hash(x,n)),a=r()*Math.PI*2,d=Math.sqrt(r());c.fillRect(x+Math.cos(a)*d*(rx-12),y-5+Math.sin(a)*d*(ry-6),3+Math.floor(r()*6),2);}c.fillStyle='#477f3e';for(let n=0;n<32;n++){const a=n*Math.PI*2/32,xx=x+Math.cos(a)*(rx-4),yy=y-5+Math.sin(a)*ry;c.fillRect(xx,yy-3,2,6);}};
 const enemyGround=H*.44,allyGround=H*.92,enemySize=Math.min(300,H*.62),allySize=Math.min(360,H*.82);platform(735,enemyGround,163,Math.min(30,H*.065));platform(260,allyGround,210,Math.min(43,H*.08));
 const ally=s.spirits.find(i=>i.id===battle.ally);
 drawSpirit(c,spOf(battle.enemy),battle.enemy.appearance,735-enemySize/2+(anim?.side==='b'?anim.offset:0),enemyGround-enemySize+4,enemySize);
 drawSpirit(c,spOf(ally),ally.appearance,260-allySize/2+(anim?.side==='a'?anim.offset:0),allyGround-allySize+4,allySize,true);
}
function enemyChoice(){const en=battle.enemy,sp=spOf(en);let move=E.pick(sp.moves,Math.random);if(en.hp<E.stats(en,sp).hp*.3&&sp.moves.some(m=>m.effect==='heal')&&Math.random()<.65)move=sp.moves.find(m=>m.effect==='heal');return{move,style:E.pick(['normal','normal','agile','strong'],Math.random),commit:.3+Math.random()*.5,borrow:battle.trainer&&s.rank>=2&&en.pp>25&&Math.random()<.18?1:0};}
async function doBattle(overrideMove=null){if(!battle||actionBusy)return;actionBusy=true;const i=s.spirits.find(i=>i.id===battle.ally);const result=E.resolveTempoRound(i,spOf(i),battle.enemy,spOf(battle.enemy),{move:overrideMove||spOf(i).moves[selectedMove],style,commit,borrow},enemyChoice(),battle.credits||{a:0,b:0});await animateEvents(result.events);actionBusy=false;battle.log.push(...result.log);battle.credits=result.nextCredits;if(result.nextCredits.b)battle.log.push('Your opponent receives '+result.nextCredits.b+' bonus action(s) next round.');if(result.nextCredits.a)battle.log.push('Your spirit receives '+result.nextCredits.a+' bonus action(s) next round.');borrow=0;battle.message=battle.log.at(-1);battleMode='main';battle.round++;finishRound();}
async function enemyOnly(message){if(!battle||actionBusy)return;actionBusy=true;if(message)battle.log.push(message);const i=s.spirits.find(i=>i.id===battle.ally),c=enemyChoice();for(let n=0;n<1+(battle.credits?.b||0)&&i.hp>0;n++){await playMoveAnimation('b',c.move,c.style);battle.log.push(...E.executeAction(battle.enemy,spOf(battle.enemy),i,spOf(i),c.move,c.style,c.commit,Math.random,1+n*.5));}actionBusy=false;battle.credits={a:0,b:0};borrow=0;battle.message=battle.log.at(-1);battleMode='main';battle.round++;finishRound();}
function finishRound(){if(battle.enemy.hp<=0){winBattle();return;}const i=s.spirits.find(i=>i.id===battle.ally);if(i.hp<=0){const next=party().find(p=>p.hp>0);if(!next){loseBattle();return;}battle.log.push(spOf(i).forms[i.appearance]+' retreats into its seal. '+spOf(next).forms[next.appearance]+' steps forward.');battle.ally=next.id;commit=next.commit;}save();render();}
function winBattle(){const won=battle,ally=s.spirits.find(i=>i.id===won.ally),sp=spOf(ally),xp=won.enemy.level*(won.trainer?35:24),previous=ally.appearance,result=E.gainXP(ally,sp,xp);if(result.evolved)transformSpirit(sp,previous,ally.appearance);ally.bond=Math.min(100,ally.bond+4);s.wins++;const reward=won.trainer?35+s.rank*12:0;if(reward)s.inventory.coins+=reward;renown(won.trainer?45:12);if(won.trainer&&!s.quests.rival){s.quests.rival=true;s.friendships['rival-0,0']=(s.friendships['rival-0,0']||0)+8;}if(won.roamer)removeRoamer(won.roamer);battle=null;ensurePlayerOnPath();note('Won '+(won.trainer?'a guild match':'a wild battle')+' with '+sp.forms[ally.appearance]+'.');save();render();showModal(result.evolved?'A new form awakens.':'A bond grows stronger.','<div style="text-align:center">'+sprite(sp,ally.appearance,180)+'</div><p>You earned '+(reward?reward+' Coin and ':'')+xp+' experience.'+(result.levels?' '+esc(sp.forms[ally.appearance])+' reached level '+ally.level+'.':'')+(result.evolved?' Previous forms remain available as cosmetic appearances.':'')+'</p><div class="btn-row">'+action('close','Continue exploring','','btn primary')+'</div>');}
function loseBattle(){const items={seals:Math.floor(s.inventory.seals/3),offerings:Math.floor(s.inventory.offerings/3),tonics:Math.floor(s.inventory.tonics/3),ethers:Math.floor((s.inventory.ethers||0)/3)};for(const k of Object.keys(items))s.inventory[k]-=items[k];s.drops.push({x:s.player.x,y:s.player.y,items});const cost=Math.min(s.inventory.coins,20+s.rank*5);s.inventory.coins-=cost;s.player.x=s.safe.x;s.player.y=s.safe.y;party().forEach(i=>E.heal(i,spOf(i)));battle=null;save();render();showModal('Back beneath the guild lamps.','<p>A passing sealer helped you return to safety. Recovery cost '+cost+' Coin. Your dropped supplies are waiting where you fell; press E nearby to retrieve them.</p><div class="btn-row">'+action('close','Rest, then try again','','btn primary')+'</div>');}
function battleSeal(){if(!battle||battle.trainer)return;if(s.inventory.seals<1)return toast('No seal catalysts remaining.');s.inventory.seals--;const en=battle.enemy,sp=spOf(en),chance=E.sealChance(en,sp,s.inventory.quality);if(Math.random()<chance){const roamer=battle.roamer;battle=null;capture(en,roamer);save();render();}else enemyOnly('The seal flickers and breaks. Weaken or hinder the spirit to improve your chances.');}
function switchBattle(){const options=party().filter(i=>i.hp>0&&i.id!==battle.ally);if(!options.length)return toast('No other healthy attuned spirits.');showModal('Call another bond.','<p>Switching takes your action for this round.</p><div class="btn-row">'+options.map(i=>action('switch-to',esc(spOf(i).forms[i.appearance])+' · Lv. '+i.level,i.id)).join('')+'</div>');}
function profile(){showModal(s.player.name+', '+rankName(),'<p>A sealer of the '+currentRegion().biome.name+'. Your story is yours to write.</p><div class="detail-stats"><div><strong>'+s.rank+'</strong><small>Guild rank</small></div><div><strong>'+s.wins+'</strong><small>Battles won</small></div><div><strong>'+s.steps+'</strong><small>Steps taken</small></div></div><p>Renown: '+s.rankXP+' / '+s.rank*100+'<br>Wade: rank 2 and an Elemental, Ooze, or Water spirit. Climb: rank 3 and a Beast, Giant, or Construct.<br>Once per battle, Sealer’s Ward protects your spirit and consumes your action.</p><label for="rename">Sealer name</label><input id="rename" value="'+esc(s.player.name)+'" maxlength="24"><div class="btn-row">'+action('rename','Save name')+'</div>');}

function exportSave(){const payload=savePayload(),blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='spirimon-'+s.seed+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save backup exported.');}
async function importSave(file){if(!file)return;if(file.size>150*1024*1024)return toast('Backup is too large.');try{const data=JSON.parse(await file.text());if(data.format!=='spirimon-backup'||data.version!==1||!data.save?.player||!Array.isArray(data.save.spirits)||!data.save.species||typeof data.save.seed!=='string')throw Error('Not a Spirimon backup.');const next=data.save;if(!Number.isInteger(next.player.x)||!Number.isInteger(next.player.y)||!Array.isArray(next.party)||next.party.length>6)throw Error('Invalid player or party data.');for(const i of next.spirits){if(!next.species[i.species]||!Number.isFinite(i.hp)||!Number.isInteger(i.form)||i.form<0||i.form>2)throw Error('Invalid spirit data.');}for(const sp of Object.values(next.species)){if(!E.TYPES.includes(sp.base)||!E.TYPES.includes(sp.alter)||sp.base===sp.alter||sp.forms?.length!==3||sp.moves?.length!==4)throw Error('Invalid species data.');}await dbPut('saves',structuredClone(s),'before-import');s=next;installRoster();for(const sp of data.library||[])if(sp?.id&&E.TYPES.includes(sp.base)&&E.TYPES.includes(sp.alter))library[sp.id]=sp;for(const sp of Object.values(s.species))register(sp);battle=s.battle||null;closeModal();discoverRegion();await persist();render();toast('Backup restored. Your previous world was kept as a recovery save.');}catch(e){toast('Could not import: '+e.message);}}
function settings(){showModal('Your world. Your device.','<p>Link a device save file for automatic file saving when supported. Chrome on Android may not support persistent file access; use Export backup to save a file manually. Browser recovery saves remain available as a safety copy.</p><label for="layout-setting">Play layout</label><select id="layout-setting"><option value="auto">Automatic · emulator controls on phones</option><option value="emulator">Emulator · landscape touch controls</option><option value="desktop">Desktop · full-window map</option></select><div class="btn-row">'+action('fullscreen','Fullscreen / landscape')+'</div><div class="btn-row">'+action('calibrate','Calibrate audio / input')+action('music-toggle',s.settings.musicEnabled===false?'Enable music':'Mute music')+'</div><p class="help-line">Saved input offset: '+(s.settings.inputOffsetMs||0)+'ms. Perfect ±45ms · Good ±90ms · Fair ±150ms.</p><div class="btn-row">'+action('choose-device-save','Link device save file')+action('export','Save file / Export backup')+'<label class="btn" style="margin:0;cursor:pointer">Import backup<input type="file" id="import-file" accept=".json" hidden></label>'+action('restore-backup','Restore previous world','','btn ghost')+'</div><div class="modal-section"><p><a class="btn ghost" href="./Spirimon.html" download>Download standalone game</a></p><p class="help-line">For the optional local AI companion, download the full source package from the project folder.</p></div><div class="modal-section"><h3>AI Provider · automatic switching</h3><p class="help-line">Test each connection, choose a model and fallback. Text-only providers cannot create the three required sprite images; the game remains playable using existing Spirit artwork.</p><label for="ai-provider">Primary provider</label><select id="ai-provider"><option value="auto">Automatic · first available</option><option value="companion">Spirimon companion · text + sprites</option><option value="ollama">Windows Ollama · text</option><option value="device">Android on-device · WebGPU text</option><option value="gemini">Gemini cloud · text</option><option value="procedural">Procedural · offline</option></select><label for="ai-fallback">Fallback</label><select id="ai-fallback"><option value="procedural">Procedural · offline</option><option value="companion">Spirimon companion</option><option value="ollama">Windows Ollama</option><option value="device">Android on-device</option><option value="gemini">Gemini cloud</option></select><label for="ai-ollama-url">Ollama API URL (HTTPS relay required for a remote Windows PC)</label><input id="ai-ollama-url" placeholder="https://your-private-relay.example" value="'+esc(s.settings.ollamaUrl||'http://localhost:11434')+'"><label for="ai-cloud-key">Gemini API key (session only; never saved)</label><input id="ai-cloud-key" type="password" autocomplete="off" placeholder="Enter only when using Gemini"><label for="ai-provider-model">Model for selected provider</label><select id="ai-provider-model"><option value="">Test connection to discover models</option></select><div class="btn-row">'+action('ai-test-provider','Test provider')+action('ai-test-auto','Test automatic selection')+'</div><div id="ai-provider-status" class="settings-status">Not tested. Browser-based AI needs WebGPU; Windows Ollama needs a secure reachable URL.</div></div><div class="modal-section"><h3>Free local AI</h3><p style="margin-top:8px">The optional companion connects to Ollama for spirit designs and a local Stable Diffusion WebUI API for sprites. Without models, the completed original roster and your saved AI lineages keep the game playable.</p><label><input type="checkbox" id="ai-enabled" '+(s.settings.aiEnabled?'checked':'')+'> Generate future discoveries with local AI</label><label for="ai-model">Installed text model</label><select id="ai-model"><option value="">Detect installed models first</option></select><div class="btn-row">'+action('check-ai','Check companion')+action('generate-now','Queue a new lineage')+'</div><div id="ai-status" class="settings-status">Companion: '+(aiStatus?esc(aiStatus.message):'not checked')+'<br>Queue: '+queue.length+' lineages'+(busy?' · generating':'')+'</div><p class="help-line">AI-created lineages enter the library only after their text and all three sprites finish. Already discovered spirits never change.</p></div><div class="modal-section"><h3>Begin another world</h3><p>Your species library stays. Export your current save first; a recovery copy is also retained.</p><label for="new-seed">World seed (optional)</label><input id="new-seed" maxlength="40" placeholder="A word, number, or leave blank"><div class="btn-row">'+action('new-world','Prepare a new world','','btn danger')+'</div></div>',{kind:'settings'});if(aiStatus?.models)fillModels();$('#layout-setting').value=s.settings.layout||'auto';$('#ai-provider').value=s.settings.aiProvider||'auto';$('#ai-fallback').value=s.settings.aiFallback||'procedural';}
let aiSessionKey='';let aiProviderResult=null;
async function testProvider(auto=false){const out=$('#ai-provider-status');if(out)out.textContent='Testing connections…';try{const selected=s.settings.aiProvider||'auto';const result=auto||selected==='auto'?await AI.choose(s.settings,aiSessionKey):{type:selected,status:await AI.probe(selected,s.settings,aiSessionKey),errors:[]};aiProviderResult=result;const models=result.status.models||[];if(out)out.textContent='Active: '+AI.LABELS[result.type]+' · '+result.status.message+(result.errors?.length?' · Unavailable: '+result.errors.join('; '):'');const select=$('#ai-provider-model');if(select){select.innerHTML=models.map(m=>'<option value="'+esc(m)+'">'+esc(m)+'</option>').join('')||'<option value="">No models found</option>';select.value=s.settings.aiModels?.[result.type]||models[0]||'';}return result;}catch(e){if(out)out.textContent='Connection failed: '+e.message;return null;}}
function fillModels(){const select=$('#ai-model');if(!select)return;select.innerHTML=(aiStatus.models||[]).map(m=>'<option '+(m===s.settings.model?'selected':'')+'>'+esc(m)+'</option>').join('')||'<option value="">No text models installed</option>';}
async function checkAI(){const out=$('#ai-status');if(out)out.textContent='Checking local companion…';try{const response=await fetch(COMPANION+'/api/status',{signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error('Companion returned '+response.status);aiStatus=await response.json();aiStatus.message=(aiStatus.models.length?'Text models ready':'No Ollama model found')+' · '+(aiStatus.imageReady?'Image API ready':'Image API not connected');fillModels();if(out)out.textContent=aiStatus.message+' · queue '+queue.length;}catch(err){aiStatus={message:'Companion offline. Run Start-Spirimon.cmd from the downloaded game.',models:[],imageReady:false};if(out){out.textContent=aiStatus.message;out.classList.add('error');}}}
async function processQueue(){if(busy||!s.settings.aiEnabled||!queue.length)return;busy=true;const id=queue.shift(),original=s.generationPlans?.[id];if(!original){busy=false;return;}try{const route=await AI.choose(s.settings,aiSessionKey);if(route.type==='procedural'){delete s.generationPlans[id];note('AI unavailable; procedural Spirit generation remains active.');save();return;}if(route.type!=='companion'){const model=s.settings.aiModels?.[route.type]||route.status.models[0];if(!model)throw Error('No text model available');const prompt='Invent a distinct fantasy creature based on '+original.base+' and '+original.alter+'. Return a JSON object with keys forms (three distinct names) and description (one vivid paragraph). JSON only.';const response=await AI.text(route.type,{...s.settings,model,aiModels:{...s.settings.aiModels,[route.type]:model}},prompt,aiSessionKey);const result=JSON.parse(response.replace(/^\x60\x60\x60(?:json)?\s*|\s*\x60\x60\x60$/g,''));if(!Array.isArray(result.forms)||result.forms.length!==3||typeof result.description!=='string')throw Error('Model returned incomplete creature data');const base=Object.values(library).find(p=>(p?.atlas||p?.proceduralArt)&&p.base===original.base)||Object.values(library).find(p=>p?.atlas);if(!base)throw Error('No reusable sprite art available');const sp={...original,id:'ai-'+original.id+'-'+E.hash(result.forms.join('')),forms:result.forms.map(x=>String(x).slice(0,45)),description:result.description.slice(0,1200),atlas:base.atlas,sprites:[],source:'ai-text-'+route.type};register(sp);delete s.generationPlans[id];note('New '+AI.LABELS[route.type]+' text lineage: '+sp.forms[0]+' (uses existing placeholder artwork).');save();toast('AI text lineage ready with placeholder art.');return;}const model=s.settings.aiModels?.companion||s.settings.model||route.status.models[0];if(!model)throw Error('Choose an installed text model in Settings.');const existing=Object.values(library).filter(p=>p.base===original.base&&p.alter===original.alter).slice(-6).map(p=>({forms:p.forms,description:p.description}));const res=await fetch(COMPANION+'/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({species:original,model,existing}),signal:AbortSignal.timeout(900000)});const data=await res.json();if(!res.ok)throw Error(data.error||'Local generation failed');let sp=E.validateSpecies(data,original);if(!Array.isArray(data.sprites)||data.sprites.length!==3||data.sprites.some(v=>typeof v!=='string'||!v.startsWith('data:image/png;base64,')))throw Error('All three sprite images are required.');sp={...sp,id:'ai-'+original.id+'-'+E.hash(data.forms.join('')),sprites:data.sprites,atlas:null,portrait:null};register(sp);delete s.generationPlans[id];if(!s.spirits.length){const first=s.roamers['0,0']?.find(r=>r.id==='first-bond'&&r.active);if(first&&!s.seen.includes(first.ind.species))first.ind=E.heal(E.makeIndividual(sp,3),sp);}note('A new local-AI lineage is ready in the library: '+sp.forms[0]+'.');save();toast('Local AI finished a new three-form lineage.');}catch(e){queue.unshift(id);toast('AI generation paused: '+e.message);save();}finally{busy=false;if(modal==='settings')settings();}}
function drawTallGrass(c,x,y,seed,time,disturbance=0,foreground=false){
 const r=E.rng(seed),wind=Math.sin(time/650+seed%19)*1.2;
 for(let n=0;n<9;n++){
  const bx=x+3+Math.floor(r()*27),by=y+12+Math.floor(r()*18);
  const height=11+Math.floor(r()*11),sway=wind+Math.sin(time/190+n*2+seed%11)*disturbance*5;
  if(foreground&&by<y+20)continue;
  c.strokeStyle=n%3===0?'#a3c75a':n%3===1?'#568e38':'#36753b';
  c.lineWidth=n%4===0?3:2;c.beginPath();c.moveTo(bx,by);c.quadraticCurveTo(bx+sway*.45,by-height*.6,bx+sway+(n%3-1)*3,by-height);c.stroke();
  c.fillStyle='#b5d76b';c.fillRect(Math.round(bx+sway),Math.round(by-height),2,3);
 }
 c.lineWidth=1;
}
function wanderSpirits(now){if(s.interior||modal||battle||view!=='explore')return;const pos=E.coord(s.player.x,s.player.y),group=s.roamers[pos.cx+','+pos.cy]||[];for(const r of group){if(!r.active)continue;if(!r.wanderNext)r.wanderNext=now+3500+Math.random()*4500;if(now<r.wanderNext)continue;r.wanderNext=now+4500+Math.random()*6500;if(Math.random()<.3)continue;const dirs=[[1,0],[-1,0],[0,1],[0,-1]],d=dirs[Math.floor(Math.random()*dirs.length)],nx=r.x+d[0],ny=r.y+d[1],next=E.coord(nx,ny);if(next.cx!==pos.cx||next.cy!==pos.cy||!E.walkable(E.tile(s.seed,nx,ny))||buildingSpriteBlocked(nx,ny)||Math.abs(nx-s.player.x)+Math.abs(ny-s.player.y)<=1||townNPCs(pos.cx,pos.cy).some(n=>n.x===nx&&n.y===ny)||(E.region(s.seed,pos.cx,pos.cy).town&&W.buildings(pos.cx,pos.cy).some(b=>b.doorX===nx&&b.doorY===ny))||group.some(o=>o!==r&&o.active&&o.x===nx&&o.y===ny))continue;r.wanderFrom={x:r.x,y:r.y,start:now,duration:420};r.face=d[0]<0?'left':d[0]>0?'right':d[1]<0?'up':'down';r.x=nx;r.y=ny;}}
function drawWorld(time){
 const canvas=$('#world');if(!canvas||view!=='explore'||battle)return;
 if(s.interior){drawInterior(canvas,time);return;}
 const rect=canvas.getBoundingClientRect(),scale=document.body.classList.contains('emulator-mode')?1.5:2;
 const width=Math.max(240,Math.round(rect.width/scale)),height=Math.max(160,Math.round(rect.height/scale));
 if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}
 const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;
 const elapsed=walkAnim?Math.min(1,(time-walkAnim.start)/walkAnim.duration):1;
 const vx=walkAnim?walkAnim.x+(s.player.x-walkAnim.x)*elapsed:s.player.x,vy=walkAnim?walkAnim.y+(s.player.y-walkAnim.y)*elapsed:s.player.y;
 const cols=width/32,rows=height/32,ox=vx-(cols-1)/2,oy=vy-(rows-1)/2;
 const px=x=>Math.round((x-ox)*32),py=y=>Math.round((y-oy)*32);
 for(let y=Math.floor(oy)-2;y<=Math.ceil(oy+rows)+1;y++)for(let x=Math.floor(ox)-2;x<=Math.ceil(ox+cols)+1;x++){
 const reg=E.region(s.seed,Math.floor(x/48),Math.floor(y/36)),terrain=E.tile(s.seed,x,y),local=E.coord(x,y);drawTile(c,terrain,px(x),py(y),E.hash(s.seed,x,y),reg.biome.kind,{neighbors:[[0,-1],[1,0],[0,1],[-1,0]].map(([dx,dy])=>E.tile(s.seed,x+dx,y+dy)),town:reg.town&&Math.abs(local.lx-24)<10&&Math.abs(local.ly-18)<8});if(terrain==='grass'){const distance=Math.hypot(x-vx,y-vy),disturbance=walkAnim&&elapsed<1?Math.max(0,1.8-distance):0;drawTallGrass(c,px(x),py(y),E.hash(s.seed,x,y),time,disturbance);}}

 const pc=E.coord(s.player.x,s.player.y),people=[];
 for(let cy=pc.cy-1;cy<=pc.cy+1;cy++)for(let cx=pc.cx-1;cx<=pc.cx+1;cx++){
  const reg=E.region(s.seed,cx,cy);
  if(reg.town){
   for(const b of W.buildings(cx,cy)){const x=px(b.footX),y=py(b.footY);if(x>-200&&x<width+200&&y>-180&&y<height+180)drawTownBuilding(c,b,x,y);}drawTownFeatures(c,cx,cy,px,py);
   drawTownDecor(c,px(cx*48+33),py(cy*36+14));drawWell(c,px(cx*48+27),py(cy*36+18));
   people.push(...townNPCs(cx,cy));
  }

 }
 for(const n of people){const w=n.walk,progress=w?Math.min(1,(time-w.start)/w.duration):1,x=px(w&&progress<1?w.x+(n.x-w.x)*progress:n.x),y=py(w&&progress<1?w.y+(n.y-w.y)*progress:n.y);drawPerson(c,x,y-5,n.role,time,n.face||'down',progress<1);if(Math.abs(n.x-s.player.x)+Math.abs(n.y-s.player.y)<=2){c.fillStyle='#fff5bd';c.strokeStyle='#4f4430';c.font='bold 10px monospace';c.textAlign='center';c.strokeText('!',x+16,y-8);c.fillText('!',x+16,y-8);}}
 for(const d of s.drops){const x=px(d.x),y=py(d.y);c.fillStyle='#d2b17b';c.fillRect(x+9,y+9,14,15);c.fillStyle='#725b3b';c.fillRect(x+14,y+6,4,6);}
 for(let ty=Math.floor(oy)-1;ty<=Math.min(Math.floor(vy),Math.ceil(oy+rows)+2);ty++)for(let tx=Math.floor(ox)-2;tx<=Math.ceil(ox+cols)+2;tx++)if(E.tile(s.seed,tx,ty)==='tree')drawTree(c,px(tx),py(ty),E.hash(s.seed,tx,ty),E.region(s.seed,Math.floor(tx/48),Math.floor(ty/36)).biome.kind);const moving=!!walkAnim&&elapsed<1;drawPerson(c,px(vx),py(vy)-5,'player',moving?elapsed*1000:0,s.player.face,moving);for(let cy=pc.cy-1;cy<=pc.cy+1;cy++)for(let cx=pc.cx-1;cx<=pc.cx+1;cx++)for(const b of W.buildings(cx,cy)){if(vy>=b.footY&&vy<b.footY+1&&vx>=b.footX&&vx<b.footX+b.w)drawTownBuilding(c,b,px(b.footX),py(b.footY));}if(E.tile(s.seed,Math.round(vx),Math.round(vy))==='grass')drawTallGrass(c,px(Math.round(vx)),py(Math.round(vy))+7,E.hash(s.seed,Math.round(vx),Math.round(vy),'front'),time,moving?1.5:0,true);
 for(let cy=pc.cy-1;cy<=pc.cy+1;cy++)for(let cx=pc.cx-1;cx<=pc.cx+1;cx++)if(E.region(s.seed,cx,cy).town){for(const b of W.buildings(cx,cy))if(vy>=b.footY-1&&vy<=b.footY+b.h&&vx>=b.footX-2&&vx<=b.footX+b.w+1)drawTownBuilding(c,b,px(b.footX),py(b.footY));// Only draw props over the player when the player's feet are behind the prop's base.
 for(const feature of W.townFeatures()){const fx=cx*48+feature.x,fy=cy*36+feature.y+feature.h-1;if(vy<fy&&Math.abs(vx-(fx+(feature.w-1)/2))<Math.max(2,feature.w+1))drawTownFeatures(c,cx,cy,px,py,feature);}
 if(vy<cy*36+18&&Math.abs(vx-(cx*48+27))<3)drawWell(c,px(cx*48+27),py(cy*36+18));
 if(vy<cy*36+14&&Math.abs(vx-(cx*48+33))<3)drawTownDecor(c,px(cx*48+33),py(cy*36+14));}
 for(let ty=Math.floor(oy)-1;ty<=Math.ceil(oy+rows)+2;ty++)for(let tx=Math.floor(ox)-2;tx<=Math.ceil(ox+cols)+2;tx++)if(ty>vy&&E.tile(s.seed,tx,ty)==='tree')drawTree(c,px(tx),py(ty),E.hash(s.seed,tx,ty),E.region(s.seed,Math.floor(tx/48),Math.floor(ty/36)).biome.kind);
 // Render wild Spirits in the foreground, after tree canopies, so they cannot be hidden by terrain.
 for(let cy=pc.cy-1;cy<=pc.cy+1;cy++)for(let cx=pc.cx-1;cx<=pc.cx+1;cx++)for(const r of s.roamers[cx+','+cy]||[]){if(!r.active)continue;const a=r.wanderFrom,t=a?Math.min(1,(time-a.start)/a.duration):1,rx=a&&t<1?a.x+(r.x-a.x)*t:r.x,ry=a&&t<1?a.y+(r.y-a.y)*t:r.y,x=px(rx),y=py(ry);if(x<-70||x>width+50||y<-70||y>height+50)continue;try{const sp=spOf(r.ind);c.save();drawSpirit(c,sp,r.ind.appearance,x-13,y-29+(t<1?-Math.abs(Math.sin(t*Math.PI))*4:0),58,r.face==='left');c.restore();}catch(e){c.restore();console.warn('Wild Spirit drawing failed',r.id,e);}}
 drawAtmosphere(c,width,height,time);
 for(let i=0;i<7;i++){c.globalAlpha=.22;c.fillStyle=i%2?'#ffdfd5':'#f9efb8';c.fillRect((i*137+time*.006)%width,(i*83+Math.sin(time/1400+i)*10)%height,2,1);}c.globalAlpha=1;
 const coords=$('#map-coords');if(coords)coords.textContent=s.player.x+' / '+s.player.y;const hintNode=$('#map-hint');if(hintNode){const nextHint=hint();if(hintNode.textContent!==nextHint)hintNode.textContent=nextHint;}
}
function tick(time){const delta=Math.min(1000,time-lastTime);lastTime=time;if(loaded){s.playTime+=delta;if(!modal&&!battle&&view==='explore'&&time-lastStep>(walkAnim?.duration||170)){const key=[...keys].find(k=>['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(k));if(!key&&queuedStep){const next=queuedStep;queuedStep=null;move(...next);}if(key){queuedStep=null;const dir={w:[0,-1],arrowup:[0,-1],a:[-1,0],arrowleft:[-1,0],s:[0,1],arrowdown:[0,1],d:[1,0],arrowright:[1,0]}[key];move(...dir);lastStep=time;}}if(ritual){ritual.progress=(Math.sin((time-ritual.start)/(s.settings.timing==='slow'?1800:950)*Math.PI)+1)/2;const cursor=$('#ritual-cursor');if(cursor)cursor.style.left=ritual.progress*99+'%';}try{wanderSpirits(time);try{wanderNPCs(time);}catch(npcErr){console.error('NPC wandering failed',npcErr);}drawWorld(time);}catch(err){console.error('Spirimon world frame failed',err);const world=$('#world');if(world){const ctx=world.getContext('2d');if(ctx){ctx.fillStyle='#f4ebc9';ctx.fillRect(0,0,world.width,world.height);ctx.fillStyle='#5b302a';ctx.font='16px monospace';ctx.fillText('Map rendering error',20,38);ctx.font='12px monospace';ctx.fillText(String(err.message||err).slice(0,90),20,62);}}const hint=$('#map-hint');if(hint)hint.textContent='Map error: '+String(err.message||err).slice(0,100);}}requestAnimationFrame(tick);}
document.addEventListener('click',async ev=>{if(ev.target.classList.contains('modal-overlay')){if(modal&&modal!=='welcome')closeModal();return;}const btn=ev.target.closest('[data-action]');if(!btn||btn.disabled||actionBusy)return;ev.preventDefault();const a=btn.dataset.action,v=btn.dataset.value;switch(a){
case'free-first-seal':{const r=findRoamer(v);if(!r?.active||s.spirits.length!==0){toast('The free first seal is no longer available.');break;}capture(structuredClone(r.ind),r.id);closeModal();render();toast('Your first Spirit is sealed and attuned — no offerings spent!');break;}
 case'begin-journey':s.player.name=$('#sealer-name')?.value.trim().slice(0,24)||'Sealer';s.starter=true;closeModal();save();render();break;
case'emu-a':interact();break;
case'emu-b':if(modal)closeModal();break;
case'game-menu':gameMenu();break;
case'save-now':await persist();closeModal();toast(deviceSaveHandle?'Save requested. Check file permission if browser recovery is shown.':'Saved to browser recovery. Use Save file / Export backup for a device file.');break;
case'fullscreen':await enterFullscreen();break;
case'portrait-play':s.settings.portraitAllowed=true;applyLayout();save();break;
case'view':if(battle&&v!=='explore')return toast('Finish the encounter first.');closeModal();view=v;render();break;
case'close':closeModal();break;
case'starter':chooseStarter(v);break;
case'step':move(...{up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[v]);break;
case'interact':interact();break;
case'detail':detail(v);break;
case'attune':attune(v);break;
case'lead':if(battle)return toast('Use Switch spirit during battle.');if(!s.party.includes(v))return toast('Attune this spirit first.');s.party=[v,...s.party.filter(x=>x!==v)];save();detail(v);render();break;
case'learn-menu':learnMenu(v);break;
case'learn-slot':{const[id,slot]=v.split(':');learnMenu(id,Number(slot));break;}
case'learn-move':{const[id,slot,moveId]=v.split('|');const i=s.spirits.find(x=>x.id===id),sp=spOf(i);if(!safe()||!sp.learnset.some(m=>m.id===moveId))break;i.moveIds=sp.moves.map(m=>m.id);i.moveIds[Number(slot)]=moveId;save();detail(id);break;}
case'appearance':{if(battle)return toast('Change appearance outside battle.');const[id,n]=v.split(':'),i=s.spirits.find(x=>x.id===id);if(i&&Number(n)<=i.form){const previous=i.appearance;i.appearance=Number(n);save();detail(id);render();transformSpirit(spOf(i),previous,i.appearance);}break;}
case'train':training(v);break;
case'bond':shareOffering(v);break;
case'rest':rest();break;
case'rest-close':closeModal();rest();break;
case'collection-close':closeModal();view='spirits';render();break;
case'bag':bag();break;
case'offer':cooperate(v,true);break;
case'observe':cooperate(v,false);break;
case'wild-battle':{const r=findRoamer(v);if(r?.active)startBattle(r.ind,v);break;}
case'seal-pulse':sealPulse();break;
case'chat':chat(v);break;
case'buy':buy(v);break;
case'claim':claim(v);break;
case'trainer':trainerBattle();break;
case'npc-trade':tradeSpirit();break;
case'confirm-trade':{if(!s.trade)return;const{out,incoming}=s.trade;if(s.party.includes(out))return;s.spirits=s.spirits.filter(i=>i.id!==out);s.spirits.push(incoming);discover(spOf(incoming));delete s.trade;save();closeModal();render();toast('The exchange is complete. A new spirit rests in your tattoos.');break;}
case'trade-items':if(s.inventory.seals<3)return toast('You need three seal catalysts.');s.inventory.seals-=3;s.inventory.tonics++;save();talk(s.activeNPC);render();toast('Trade complete.');break;
case'move-select':selectedMove=Number(v);battleMode='tactics';render();break;
case'battle-fight':case'battle-moves':battleMode='moves';render();break;
case'battle-main':battleMode='main';render();break;
case'battle-bag':battleMode='bag';render();break;
case'battle-record':showModal('Battle record.','<div class="battle-record-list">'+battle.log.slice(-25).map(t=>'<p>'+esc(t)+'</p>').join('')+'</div>');break;
case'yield':battle=null;save();render();toast('You concede the friendly match.');break;
case'style':style=v;render();break;
case'borrow':borrow=Number(v);render();break;
case'ether':useEther();break;
case'omega-act':{const ally=s.spirits.find(i=>i.id===battle?.ally);if(!ally||ally.omegaUsed||actionBusy)break;const base=spOf(ally).moves[selectedMove];if(E.moveCategory(base)==='Status')break;ally.omegaUsed=true;const sp=spOf(ally),boost={...base,id:'omega-'+base.id,name:'Omega '+base.name,power:Math.max(90,Math.round(base.power*2.2)),ppCost:0,omega:true};await doBattle(boost);save();break;}
case'battle-act':doBattle();break;
case'battle-seal':battleSeal();break;
case'battle-switch':switchBattle();break;
case'switch-to':{if(!battle)return;const i=party().find(i=>i.id===v&&i.hp>0);if(!i)return;battle.ally=v;commit=i.commit;selectedMove=0;closeModal();enemyOnly('You call '+spOf(i).forms[i.appearance]+' into battle.');break;}
case'tonic':useTonic();break;
case'support':if(!battle||battle.supportUsed)return toast('Sealer’s Ward can be used once per battle.');battle.supportUsed=true;s.spirits.find(i=>i.id===battle.ally).ward=true;enemyOnly('Your tattoo glows. Sealer’s Ward softens the incoming blow.');break;
case'flee':if(!battle||battle.trainer)return;battle=null;ensurePlayerOnPath();save();render();toast('You withdraw safely.');break;
case'settings':settings();break;
case'profile':profile();break;
case'rename':s.player.name=$('#rename').value.trim().slice(0,24)||'Sealer';save();closeModal();render();break;
case'export':exportSave();break;
case'choose-device-save':await chooseDeviceSave();break;
case'calibrate':O.calibrateInput({settings:s.settings,persist,open:(title,html)=>showModal(title,html,{kind:'calibration'})});break;
case'music-toggle':s.settings.musicEnabled=s.settings.musicEnabled===false;audio.setEnabled(s.settings.musicEnabled);save();settings();break;
case'check-ai':await checkAI();break;
case'ai-test-provider':await testProvider(false);break;
case'ai-test-auto':await testProvider(true);break;
case'generate-now':{if(!s.settings.aiEnabled)return toast('Enable local AI generation first.');queueFresh(currentRegion(),Math.random,true);toast('Lineage queued. All three forms must finish before entering the AI library.');processQueue();break;}
case'new-world':{if(battle)return toast('Finish the battle first.');s.pendingSeed=$('#new-seed').value.trim();showModal('Start a new journey?','<p>Your current world will be retained as a recovery copy. Export a backup too if you want to keep it permanently. Your shared spirit library stays available.</p><div class="btn-row">'+action('confirm-new','Start new world','','btn danger')+action('export','Export current world')+action('close','Cancel','','btn ghost')+'</div>');break;}
case'confirm-new':{await dbPut('saves',structuredClone(s),'before-import');const seed=s.pendingSeed;s=E.newGame(seed||undefined);installRoster();battle=null;queue=[];view='explore';closeModal();discoverRegion();introduceFirstEncounter();render();starters();save();break;}
case'restore-backup':{const backup=await dbGet('saves','before-import');if(!backup)return toast('No recovery world is stored yet.');const current=structuredClone(s);s=backup;battle=s.battle||null;await dbPut('saves',current,'before-import');closeModal();discoverRegion();save();render();toast('Previous world restored.');break;}
case'interact':interact();break;
case'mini-region':{const r=s.regions[v];if(r?.visited)showModal(r.name,'<p>'+esc(r.biome.name)+' · Level '+r.danger+'+ · Region '+esc(v)+'</p><p>Explore this region from the world map.</p>');break;}
case'field-menu':fieldMenu();break;
case'field-use':{const [kind,key]=v.split(':');closeModal();fieldTravel(kind,key);break;}
case'party-up':{const n=s.party.indexOf(v);if(n>0&&!battle){[s.party[n-1],s.party[n]]=[s.party[n],s.party[n-1]];save();render();}break;}
case'party-down':{const n=s.party.indexOf(v);if(n>=0&&n<s.party.length-1&&!battle){[s.party[n+1],s.party[n]]=[s.party[n],s.party[n+1]];save();render();}break;}
case'region-info':{const r=s.regions[v];showModal(r.name,'<p>'+esc(r.biome.desc)+'<br>Biome: '+esc(r.biome.name)+'<br>Stable danger: level '+r.danger+' and above<br>'+(r.town?'A guild settlement offers recovery, supplies, and familiar faces.':'Wilderness region. Follow the crossing trails to keep exploring.')+'</p>');break;}
}});
document.addEventListener('input',ev=>{if(ev.target.id==='commitment')commit=Number(ev.target.value)/100;if(ev.target.id==='spirit-search'){const pos=ev.target.selectionStart;search=ev.target.value.toLowerCase();render();$('#spirit-search').focus();$('#spirit-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',ev=>{if(ev.target.id==='borrow-select'){borrow=Number(ev.target.value);render();}if(ev.target.id==='layout-setting'){s.settings.layout=ev.target.value;applyLayout();save();}if(ev.target.id==='starter-base'){s.player.name=$('#sealer-name').value||'Sealer';starterBase=ev.target.value;starters();}if(ev.target.id==='spirit-filter'){filter=ev.target.value;render();}if(ev.target.id==='timing-setting'){s.settings.timing=ev.target.value;save();}if(ev.target.id==='import-file')importSave(ev.target.files[0]);if(ev.target.id==='ai-provider'){s.settings.aiProvider=ev.target.value;save();}if(ev.target.id==='ai-fallback'){s.settings.aiFallback=ev.target.value;save();}if(ev.target.id==='ai-ollama-url'){s.settings.ollamaUrl=ev.target.value.trim();save();}if(ev.target.id==='ai-cloud-key'){aiSessionKey=ev.target.value;}if(ev.target.id==='ai-provider-model'&&aiProviderResult){s.settings.aiModels??={};s.settings.aiModels[aiProviderResult.type]=ev.target.value;save();}if(ev.target.id==='ai-enabled'){s.settings.aiEnabled=ev.target.checked;save();if(ev.target.checked)checkAI();}if(ev.target.id==='ai-model'){s.settings.model=ev.target.value;save();}});
document.addEventListener('keydown',ev=>{const k=ev.key.toLowerCase();if(['INPUT','SELECT','TEXTAREA'].includes(ev.target.tagName)&&ev.target.type!=='range')return;if(k==='escape'){if(modal==='starter'||modal==='welcome')return;closeModal();return;}if(modal){if(ritual&&(k===' '||k==='enter')){ev.preventDefault();sealPulse();}return;}if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))ev.preventDefault();keys.add(k);if(ev.repeat)return;const walkKeys={w:[0,-1],a:[-1,0],s:[0,1],d:[1,0],arrowup:[0,-1],arrowleft:[-1,0],arrowdown:[0,1],arrowright:[1,0]};if(walkKeys[k]){move(...walkKeys[k]);return;}if(k==='e'||k==='enter')interact();if(k==='b')bag();if(['1','2','3','4'].includes(k)&&!battle){view=['explore','spirits','atlas','journal'][Number(k)-1];render();}});
document.addEventListener('keyup',ev=>keys.delete(ev.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();running=false;queuedStep=null;});document.addEventListener('visibilitychange',()=>{keys.clear();persist();});window.addEventListener('pagehide',()=>persist());
async function boot(){try{db=await openDB();for(const sp of await dbAll('library'))library[sp.id]=sp;s=await dbGet('saves','main')||E.newGame();s.species??={};s.spirits=Array.isArray(s.spirits)?s.spirits:[];s.roamers??={};for(const [key,group]of Object.entries(s.roamers))if(!Array.isArray(group))s.roamers[key]=[];s.regions??={};s.inventory??={};s.settings??={};battle=s.battle||null;queue=s.generationQueue||[];s.inventory.ethers??=3;s.inventory.herbs??=3;s.inventory.incense??=2;s.inventory.ore??=2;audio.setEnabled(s.settings.musicEnabled!==false);loaded=true;await restoreDeviceSaveHandle();installRoster();normalizeWildPopulation();for(const i of s.spirits){const sp=s.species[i.species];if(sp)i.pp??=E.stats(i,sp).pp;}upgradeWildLevels();globalThis.spirimonSpecies=s.species;discoverRegion();introduceFirstEncounter();if(!battle)ensurePlayerOnPath();render();if(!s.starter)starters();if(s.settings.aiEnabled){queueFresh(currentRegion(),Math.random,true);checkAI().then(processQueue);}globalThis.spirimonArtLoaded=()=>{renderSpiritCanvases();if(battle)drawBattle();};requestAnimationFrame(tick);setInterval(persist,15000);setInterval(processQueue,5000);}catch(err){$('#main').innerHTML='<div class="panel"><h1>Local storage is unavailable.</h1><p>Open Spirimon through Start-Spirimon.cmd in a regular browser window with site storage enabled.</p><p>'+esc(err.message)+'</p></div>';console.error(err);}}
boot();

function tempoHTML(ind,sp){const credits=battle.credits||{a:0,b:0},move=sp.moves[selectedMove],count=1+credits.a+borrow;let cost=0;for(let n=0;n<count;n++)cost+=E.actionCost(move,n);return'<div class="tempo-panel"><div class="commitment-label"><span>BORROW ACTIONS</span><span>Shared PP cost: '+cost+'</span></div><div class="style-selector">'+[0,1,2].map(n=>'<button class="'+(borrow===n?'selected':'')+'" data-action="borrow" data-value="'+n+'">'+(n===0?'Normal action':'Borrow +'+n)+'</button>').join('')+'</div><p class="tiny muted">'+(credits.a?'You have '+credits.a+' bonus action(s) owed this round. ':'')+(credits.b?'Opponent has '+credits.b+' bonus action(s) this round. ':'')+(borrow?'Repeat your selected move '+count+' times if PP allows. Opponent gains '+borrow+' extra action(s) next round.':'Later actions cost 1.5×, 2×, then more PP. Bonus actions never create further debt.')+'</p></div>';}
function useEther(){if(!(s.inventory.ethers>0))return toast('Buy soul draughts from Tavi.');const i=battle?s.spirits.find(x=>x.id===battle.ally):lead();if(!i)return;const max=E.stats(i,spOf(i)).pp;if(i.pp>=max)return toast('Your spirit’s PP pool is full.');s.inventory.ethers--;i.pp=Math.min(max,i.pp+Math.ceil(max*.6));closeModal();if(battle)enemyOnly('A soul draught restores your shared PP.');else{save();render();toast('Your spirit’s shared PP is restored.');}}

function applyLayout(){const mobile=s.settings.layout==='emulator'||s.settings.layout!=='desktop'&&(matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0);document.body.classList.toggle('emulator-mode',mobile);document.body.classList.toggle('exploring',view==='explore'&&!battle);document.body.classList.toggle('battling',!!battle);document.body.classList.toggle('portrait-allowed',!!s.settings.portraitAllowed);if(!$('#emulator-shell')){const shell=document.createElement('div');shell.id='emulator-shell';shell.innerHTML='<div class="emulator-controls"><div class="emu-pad"><span class="emu-pad-center"></span><button data-hold="up" aria-label="Move up">▲</button><button data-hold="left" aria-label="Move left">◀</button><button data-hold="right" aria-label="Move right">▶</button><button data-hold="down" aria-label="Move down">▼</button></div><div class="emu-ab">'+'<button data-action="emu-b" data-run="true" aria-label="Run, hold B">B</button>'+action('emu-a','A','','')+'</div><div class="emu-menu">'+action('game-menu','MENU','','')+action('bag','BAG','','')+action('fullscreen','⛶','','')+'</div></div>'+action('view','← Return to game','explore','mobile-return')+'<div class="portrait-prompt"><div class="rotate-icon">▱ ↻</div><h2>A world worth turning for.</h2><p>Rotate your phone sideways for the full Spirimon experience, with emulator-style controls.</p>'+action('fullscreen','Play in landscape','','btn primary')+'<div style="margin-top:12px">'+action('portrait-play','Continue in portrait','','btn ghost')+'</div></div>';document.body.appendChild(shell);}}
async function enterFullscreen(){try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();if(screen.orientation?.lock)await screen.orientation.lock('landscape');}catch{toast('Rotate your phone sideways to play in landscape.');}}
document.addEventListener('pointerdown',ev=>{const button=ev.target.closest('[data-hold]');if(!button){if(ev.target.closest('[data-run]')){ev.preventDefault();running=true;}return;}ev.preventDefault();const dir=button.dataset.hold,key={up:'w',left:'a',right:'d',down:'s'}[dir];button.setPointerCapture?.(ev.pointerId);button.classList.add('held');move(...{up:[0,-1],left:[-1,0],right:[1,0],down:[0,1]}[dir]);keys.add(key);});
function releaseTouch(ev){if(ev.target.closest('[data-run]'))running=false;const button=ev.target.closest('[data-hold]');if(button){keys.delete({up:'w',left:'a',right:'d',down:'s'}[button.dataset.hold]);button.classList.remove('held');}}
document.addEventListener('pointerup',releaseTouch);document.addEventListener('pointercancel',()=>{keys.clear();running=false;document.querySelectorAll('.held').forEach(b=>b.classList.remove('held'));});window.addEventListener('resize',()=>{if(loaded)applyLayout();});

function installRoster(){s.rosterRevision=1;for(const row of ROSTER){const sp={...E.makeSpecies('roster-'+row.id,row.base,row.alter,[]),id:'roster-'+row.id,name:row.forms[1],forms:row.forms,description:row.description,atlas:row.atlas,proceduralArt:!!row.proceduralArt,source:'original-roster'};register(sp);}const originals=ROSTER.map(r=>s.species['roster-'+r.id]);for(const ind of [...s.spirits,...Object.values(s.roamers).flat().map(r=>r.ind),...(battle?.enemy?[battle.enemy]:[])]){if(!ind||!ind.species)continue;const old=s.species[ind.species];if(old?.atlas||old?.proceduralArt||old?.sprites?.length===3)continue;const replacement=originals.find(p=>p.base===old?.base&&p.alter===old?.alter)||originals[E.hash(ind.species)%originals.length];ind.species=replacement.id;ind.hp=Math.min(ind.hp,E.stats(ind,replacement).hp);}for(const [id,p]of Object.entries(s.species))if(!p.atlas&&!p.proceduralArt&&p.sprites?.length!==3){delete s.species[id];delete library[id];}for(const [id,p]of Object.entries(library))if(!p.atlas&&!p.proceduralArt&&p.sprites?.length!==3)delete library[id];for(const sp of Object.values(s.species))E.refreshTechniques(sp);}

function gameMenu(){showModal('Sealer’s satchel.','<p>'+esc(s.player.name)+' · '+rankName()+' · '+s.inventory.coins+' Coin</p><div class="menu-grid">'+action('view','SPIRITS','spirits')+action('bag','BAG')+action('view','MAP','atlas')+action('field-menu','FIELD SKILLS')+action('view','JOURNAL','journal')+action('profile','SEALER')+action('settings','OPTIONS')+action('save-now','SAVE')+action('close','RETURN','','btn primary')+'</div><p class="help-line">WASD / arrows: walk · Shift: run · E: interact<br>On touch: hold a direction; hold B to run.</p>');}

async function playMoveAnimation(side,move,moveStyle='normal'){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,duration=reduced?80:moveStyle==='agile'?280:moveStyle==='strong'?520:390;
 const speech=$('#battle-speech');if(speech&&battle){const actor=side==='a'?s.spirits.find(i=>i.id===battle.ally):battle.enemy;speech.textContent=spOf(actor).forms[actor.appearance]+' used '+move.name+'!';}const actorSp=battle?spOf(side==='a'?s.spirits.find(i=>i.id===battle.ally):battle.enemy):null;const visual=move.visual||(move.domain?.toLowerCase())||(move.type==='Plant'?'leaf':move.type==='Elemental'?(actorSp?.description.includes('crystal')?'ice':'fire'):move.type==='Ooze'?'water':'spirit');const start=performance.now(),color=({water:'#6bc9ef',fire:'#ee8a3d',ice:'#b2ecff',leaf:'#8ac95d'})[visual]||E.COLORS[move.type]||'#e5b457',from=side==='a'?{x:260,y:($('#battle-canvas')?.height||550)*.72}:{x:735,y:($('#battle-canvas')?.height||550)*.31},to=side==='a'?{x:735,y:($('#battle-canvas')?.height||550)*.31}:{x:260,y:($('#battle-canvas')?.height||550)*.72},self=['heal','ward'].includes(move.effect);
 return new Promise(resolve=>{const frame=time=>{const p=Math.min(1,(time-start)/duration),lunge=move.kind==='physical'&&!self?Math.sin(p*Math.PI)*55:0;drawBattle({side,offset:side==='a'?lunge:-lunge});const canvas=$('#battle-canvas');if(!canvas){resolve();return;}const c=canvas.getContext('2d');c.save();c.imageSmoothingEnabled=false;
 if(reduced){c.globalAlpha=Math.sin(p*Math.PI)*.25;c.fillStyle=color;c.fillRect((self?from:to).x-100,(self?from:to).y-100,200,180);}
 else if(move.effect==='heal'){for(let n=0;n<8;n++){const x=from.x+Math.sin(n*2.1)*65,y=from.y+30-p*100+(n%3)*15;c.fillStyle=n%2?'#e7ffb5':'#6abd6b';c.fillRect(x-2,y-9,5,18);c.fillRect(x-8,y-3,17,5);}}
 else if(move.effect==='ward'){c.strokeStyle='#8ccfe3';c.lineWidth=6;c.globalAlpha=Math.sin(p*Math.PI);c.beginPath();c.ellipse(from.x,from.y-30,45+12*p,65,0,0,Math.PI*2);c.stroke();c.strokeStyle='#effbd1';c.lineWidth=2;c.stroke();}
 else if(move.kind==='physical'){const impact=Math.max(0,(p-.35)/.65);for(let n=0;n<9;n++){const angle=n*Math.PI*2/9,dist=impact*65;c.fillStyle=n%2?'#fff3a6':color;const x=to.x+Math.cos(angle)*dist,y=to.y-25+Math.sin(angle)*dist;c.fillRect(x,y,5+impact*7,5);}if(p>.3&&p<.8){c.strokeStyle='#fff9df';c.lineWidth=7;c.beginPath();c.moveTo(to.x-25,to.y-60);c.lineTo(to.x+20,to.y-5);c.moveTo(to.x+25,to.y-65);c.lineTo(to.x-20,to.y);c.stroke();}}
 else if(['water','fire','ice','leaf'].includes(visual)){const travel=Math.min(1,p*1.6);c.globalAlpha=.12;c.fillStyle=color;c.fillRect(0,0,1000,canvas.height);c.globalAlpha=1;for(let n=0;n<27;n++){const t=Math.max(0,travel-n*.018),xx=from.x+(to.x-from.x)*t,yy=from.y+(to.y-from.y)*t+Math.sin(n*1.7+p*20)*12,sz=8+(27-n)*.45;if(visual==='water'){c.fillStyle=n%3?'#60bce2':'#c3f2fc';c.fillRect(xx-sz,yy-sz,sz*2,sz*1.6);c.fillStyle='#e8fcff';c.fillRect(xx-sz+2,yy-sz+2,sz*.6,3);}else if(visual==='fire'){c.fillStyle=n%3?'#eb793b':'#f5d47d';c.beginPath();c.moveTo(xx,yy-sz*2);c.lineTo(xx+sz,yy+sz);c.lineTo(xx-sz,yy+sz);c.fill();}else if(visual==='ice'){c.fillStyle=n%2?'#6ebcdd':'#e9fcff';c.beginPath();c.moveTo(xx,yy-sz*1.7);c.lineTo(xx+sz*.65,yy);c.lineTo(xx,yy+sz*1.7);c.lineTo(xx-sz*.65,yy);c.fill();}else{c.fillStyle=n%2?'#609d40':'#b5d878';c.fillRect(xx-sz,yy-3,sz*2,6);c.fillRect(xx-4,yy-sz*.6,8,sz*1.2);}}if(p>.6){c.strokeStyle=color;c.lineWidth=7;c.beginPath();c.arc(to.x,to.y-15,(p-.6)*170,0,Math.PI*2);c.stroke();}}
 else{const travel=Math.min(1,p*1.6),x=from.x+(to.x-from.x)*travel,y=from.y+(to.y-from.y)*travel-Math.sin(travel*Math.PI)*70;c.fillStyle=color;c.shadowColor=color;c.shadowBlur=15;for(let n=0;n<9;n++){const phase=p*12+n,rx=x-Math.cos(phase)*n*3,ry=y+Math.sin(phase)*n*3;c.fillRect(rx-5,ry-5,10,10);}c.shadowBlur=0;if(p>.55){const radius=(p-.55)*145;c.strokeStyle=color;c.lineWidth=6;c.beginPath();c.arc(to.x,to.y-20,radius,0,Math.PI*2);c.stroke();for(let n=0;n<8;n++){const a=n*Math.PI/4;c.fillStyle=n%2?'#fff4bd':color;c.fillRect(to.x+Math.cos(a)*radius,to.y-20+Math.sin(a)*radius,8,8);}}}
 c.restore();if(p<1)requestAnimationFrame(frame);else{drawBattle();resolve();}};requestAnimationFrame(frame);});
}
async function animateEvents(events){document.body.classList.add('battle-animating');for(const e of events||[]){await playMoveAnimation(e.side,e.move,e.style);if(!battle)break;const ally=s.spirits.find(i=>i.id===battle.ally),enemy=battle.enemy;for(const[selector,ind,sp,hp,pp]of[['.classic-hud.ally',ally,spOf(ally),e.aHP,e.aPP],['.classic-hud.enemy',enemy,spOf(enemy),e.bHP,e.bPP]]){const panel=$(selector);if(!panel)continue;const health=panel.querySelector('.health i'),power=panel.querySelector('.pp-meter i'),labels=panel.querySelectorAll('.health-label span:last-child');if(health)health.style.width=hp/E.stats(ind,sp).hp*100+'%';if(power)power.style.width=pp/E.stats(ind,sp).pp*100+'%';if(labels[0])labels[0].textContent=hp+' / '+E.stats(ind,sp).hp;if(labels[1])labels[1].textContent=pp+' / '+E.stats(ind,sp).pp;}}document.body.classList.remove('battle-animating');}

function normalizeWildPopulation(){if(!s.roamers||typeof s.roamers!=='object')s.roamers={};for(const [key,group]of Object.entries(s.roamers)){if(!Array.isArray(group)){s.roamers[key]=[];continue;}const valid=group.filter(r=>r&&r.ind&&Number.isFinite(r.x)&&Number.isFinite(r.y)&&s.species[r.ind.species]);const active=valid.filter(r=>r.active);if(active.length>7){const keep=new Set(active.slice(0,7));for(const r of active)if(!keep.has(r))r.active=false;}s.roamers[key]=valid.filter(r=>r.active||!String(r.id).startsWith('nearby-')&&!String(r.id).startsWith('visible-'));}}
function introduceFirstEncounter(){if(s.spirits.length)return;const existing=(s.roamers['0,0']||[]).some(r=>r.active&&Math.abs(r.x-s.player.x)<=5&&Math.abs(r.y-s.player.y)<=4);if(existing)return;const sp=speciesFor(currentRegion(),Math.random);s.roamers['0,0'].push({id:'first-bond',x:26,y:20,active:true,ind:E.heal(E.makeIndividual(sp,3),sp)});s.firstEncounterPlaced=true;save();}

function speedHint(){if(!battle)return'';const i=s.spirits.find(i=>i.id===battle.ally),p=spOf(i).moves[selectedMove].speed+E.STYLES[style].speed;return p>=12?'LIKELY FAST':p<=-12?'LIKELY SLOW':'NORMAL PACE';}

function ensurePlayerOnPath(){if(E.walkable(E.tile(s.seed,s.player.x,s.player.y),abilityReady('swim'),abilityReady('climb'))&&!buildingSpriteBlocked(s.player.x,s.player.y))return;for(let radius=1;radius<18;radius++)for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++)if(E.walkable(E.tile(s.seed,s.player.x+dx,s.player.y+dy))&&!buildingSpriteBlocked(s.player.x+dx,s.player.y+dy)){s.player.x+=dx;s.player.y+=dy;walkAnim=null;return;}}

function enterBuilding(building){if(modal||battle)return;s.interior=W.makeInterior(building);walkAnim=null;keys.clear();save();render();toast(building.name);}
function moveInside(dx,dy){if(modal||battle||view!=='explore')return;const room=s.interior,x=room.x+dx,y=room.y+dy;room.face=dx<0?'left':dx>0?'right':dy<0?'up':'down';const npc=W.roomNPCs(room).find(n=>n.x===x&&n.y===y);if(npc)return talk(npc);if(!W.roomWalkable(room.kind,x,y))return;if(y===10&&x===7){s.player.x=room.outside.x;s.player.y=room.outside.y;s.player.face='down';delete s.interior;keys.clear();save();render();return;}room.x=x;room.y=y;s.steps++;lastStep=performance.now();save();$('#map-hint').textContent=hint();}
function drawInterior(canvas,time){const rect=canvas.getBoundingClientRect(),width=Math.max(320,Math.round(rect.width/2)),height=Math.max(200,Math.round(rect.height/2));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}const c=canvas.getContext('2d'),room=s.interior,unit=32,ox=Math.round(width/2-room.x*unit-16),oy=Math.round(height/2-room.y*unit-16);c.imageSmoothingEnabled=false;c.fillStyle='#302b25';c.fillRect(0,0,width,height);for(let y=0;y<11;y++)for(let x=0;x<15;x++){const t=W.roomTile(room.kind,x,y),px=ox+x*unit,py=oy+y*unit;c.fillStyle={wall:'#534737','wall-art':'#c8b08a',floor:'#ba986b',rug:'#985752',tatami:'#b2b36f',exit:'#e3d9ae',bed:'#e6ded0',shelf:'#66523a',counter:'#785639',table:'#8c6845',altar:'#886446',cushion:'#b36b59'}[t];c.fillRect(px,py,32,32);c.strokeStyle='#4a38284a';c.strokeRect(px,py,32,32);if(t==='floor'||t==='tatami'){c.fillStyle='#9b7b512b';c.fillRect(px,py+14,32,2);}if(t==='shelf'){for(let k=0;k<4;k++){c.fillStyle=['#914b43','#638077','#d3bb83'][k%3];c.fillRect(px+3+k*7,py+5,5,19);}}if(t==='bed'){c.fillStyle='#70938b';c.fillRect(px+3,py+12,26,18);c.fillStyle='#f4ead2';c.fillRect(px+5,py+3,22,8);}if(t==='altar'){c.fillStyle='#eacb78';c.fillRect(px+13,py+5,6,18);}}for(const n of W.roomNPCs(room))drawPerson(c,ox+n.x*unit,oy+n.y*unit,n.role,time);drawPerson(c,ox+room.x*unit,oy+room.y*unit,'player',0,room.face);$('#map-location').textContent=room.name;$('#map-biome').textContent='MOS SVEIL · INTERIOR'.replace('MOS S','MOSS');}

function queueFresh(reg,r=Math.random,force=false){s.generationPlans??={};if(queue.length>=3&&!force)return;const base=E.pick(reg.biome.types,r),alter=E.pick(E.TYPES.filter(t=>t!==base),r),plan=E.makeSpecies(E.hash(s.seed,'ai-plan',Date.now(),r()),base,alter);s.generationPlans[plan.id]=plan;queue.push(plan.id);save();}

function learnMenu(id,slot=null){if(!safe())return toast('Practice at a safe place.');const i=s.spirits.find(x=>x.id===id);if(!i)return;const sp=spOf(i);showModal('Practice a technique.',slot===null?'<p>Choose the move slot to replace.</p><div class="btn-row">'+sp.moves.map((m,n)=>action('learn-slot',esc(m.name),id+':'+n)).join('')+'</div>':'<p>Choose a '+esc(sp.base)+' / '+esc(sp.alter)+' or domain technique.</p><div class="learn-grid">'+sp.learnset.map(m=>action('learn-move',esc(m.name)+'<small>'+m.type+(m.domain?' · '+m.domain:'')+' · Power '+m.power+' · Speed '+m.speed+'</small>',id+'|'+slot+'|'+m.id)).join('')+'</div>');}

function upgradeWildLevels(){if(s.levelRevision===2)return;s.townsVisited??=Object.values(s.regions).filter(r=>r.visited&&r.town&&r.key!=='0,0').map(r=>r.key);for(const reg of Object.values(s.regions)){Object.assign(reg,E.encounterRange(s.seed,reg.cx,reg.cy,s.townsVisited.length));reg.danger=reg.minLevel;for(const r of s.roamers[reg.key]||[]){r.ind.level=E.encounterLevel(reg,E.rng(E.hash(s.seed,r.id,'rebalance')));E.heal(r.ind,spOf(r.ind));}}s.levelRevision=2;}

document.addEventListener('pointerdown',()=>audio.unlock().catch(()=>{}),{once:true});document.addEventListener('keydown',()=>audio.unlock().catch(()=>{}),{once:true});
